    // Mapa del espectro en escala logarítmica
    bands: (() => { const X = f => 15 + (Math.log10(f) - 4) / 7 * 270; const B = [['LF', 3e4, 3e5], ['MF', 3e5, 3e6], ['HF', 3e6, 3e7], ['VHF', 3e7, 3e8], ['UHF', 3e8, 3e9], ['SHF', 3e9, 3e10]];
      const cols = ['var(--muted)', 'var(--ice)', 'var(--gem)', 'var(--ok)', 'var(--led)', 'var(--err)'];
      let s = ''; B.forEach(([n, a, b], i) => { s += `<rect x="${X(a).toFixed(1)}" y="60" width="${(X(b) - X(a)).toFixed(1)}" height="22" fill="${cols[i]}" opacity=".75"/>` + tx(((X(a) + X(b)) / 2).toFixed(1), 75, n, 'vizlab', 'middle', 'fill:#fff'); });
      const pins = [[125e3, 'RFID', 104], [1e6, 'onda media', 40], [13.56e6, 'NFC', 104], [100e6, 'FM', 40], [868e6, '868', 104], [2.44e9, 'WiFi', 40]];
      pins.forEach(([f, l, y]) => { s += ln(`M${X(f).toFixed(1)} ${y > 80 ? 84 : 58}V${y > 80 ? y - 10 : y + 4}`, 'var(--muted)', 1) + tx(X(f).toFixed(1), y, l); });
      return sv(150, s + ln('M15 92H285', 'currentColor', 1) + tx(15, 140, '10 kHz', 'vizsm', 'start') + tx(285, 140, '100 GHz', 'vizsm', 'end') + tx(150, 140, 'cada banda: ×10 en frecuencia', 'vizsm') + tx(150, 20, 'El espectro por décadas', 'vizlab')); })(),
    // Bajas frente a altas frecuencias
    trade: sv(190, tx(78, 20, 'Frecuencia baja', 'vizlab') + tx(222, 20, 'Frecuencia alta', 'vizlab') + ln('M150 30V180', 'var(--line)', 1) +
      ln('M30 70H126', 'var(--led)', 6, 'stroke-linecap="round"') + tx(78, 58, 'antena grande') + ln('M210 70H234', 'var(--led)', 6, 'stroke-linecap="round"') + tx(222, 58, 'antena pequeña') +
      `<rect x="40" y="88" width="20" height="40" fill="var(--muted)" opacity=".5"/>` + ar(20, 108, 115, 108, 'var(--ok)') + tx(78, 142, 'atraviesa bien') +
      `<rect x="200" y="88" width="20" height="40" fill="var(--muted)" opacity=".5"/>` + ar(170, 108, 196, 108, 'var(--err)') + ln('M224 108H236', 'var(--err)', 1.6, 'stroke-dasharray="3 3"') + tx(222, 142, 'se atenúa más') +
      `<rect x="48" y="156" width="60" height="12" rx="3" fill="var(--ice)" opacity=".5"/>` + tx(78, 182, 'poco ancho de banda') + `<rect x="172" y="156" width="100" height="12" rx="3" fill="var(--ice)"/>` + tx(222, 182, 'mucho ancho: más datos')),
    // Pérdidas orientativas de obstáculos
    obstacles: (() => { const R = [['Madera, pladur', 1, 5], ['Ladrillo', 5, 15], ['Hormigón armado', 15, 30], ['Cuerpo (2,4 GHz)', 3, 10], ['Caja metálica', 40, 60]];
      const X = d => 112 + d / 60 * 170; let s = '';
      R.forEach(([n, a, b], i) => { const y = 38 + i * 26; s += tx(106, y + 4, n, 'vizsm', 'end') + `<rect x="${X(a).toFixed(1)}" y="${y - 7}" width="${(X(b) - X(a)).toFixed(1)}" height="12" rx="4" fill="${b > 30 ? 'var(--err)' : b > 12 ? 'var(--led)' : 'var(--ok)'}"/>` + tx(X(b) + 4 > 250 ? X(a) - 4 : X(b) + 4, y + 4, a + '–' + b + ' dB', 'vizsm', X(b) + 4 > 250 ? 'end' : 'start'); });
      return sv(170, tx(150, 16, 'Pérdidas orientativas (mídelas siempre)', 'vizlab') + s); })(),
    // Quién regula el espectro
