    atten: sv(150, bx(10, 50, 70, 40, 'Emisor') + ln('M80 70H105', 'currentColor', 2) + `<rect x="105" y="50" width="80" height="40" rx="6" fill="var(--led)" opacity=".25" stroke="var(--led)"/>` + tx(145, 67, 'Atenuador', 'vizlab') + tx(145, 82, '−40 dB') + ln('M185 70H210', 'currentColor', 2) + bx(210, 50, 80, 40, 'Receptor SDR') +
      tx(45, 112, '+20 dBm') + tx(45, 126, '(100 mW)') + tx(250, 112, '−20 dBm') + tx(250, 126, '(10 µW: seguro)') + tx(150, 30, 'Nunca un emisor directo a una entrada sensible', 'vizlab')),
    // Cadena de un enlace en dB
    chain: sv(170, bx(6, 40, 52, 30, 'Emisor') + tx(32, 86, '+Pt dBm') + ln('M58 55H90', 'currentColor', 2) + tx(74, 47, '−cable') + ant(100, 75, 34) + tx(100, 86, '+Gt') +
      ln('M110 45C140 30 160 30 190 45', 'var(--ice)', 2, 'class="a-flow-slow"') + tx(150, 24, '−pérdidas del camino', 'vizsm', 'middle', 'fill:var(--ice)') + ant(200, 75, 34) + tx(200, 86, '+Gr') + ln('M210 55H242', 'currentColor', 2) + tx(226, 47, '−cable') + bx(242, 40, 52, 30, 'Receptor') +
      tx(150, 120, 'En dB todo se suma o se resta:', 'vizlab') + tx(150, 140, 'Pr = Pt − cable + Gt − camino + Gr − cable', 'vizlab', 'middle', 'fill:var(--led)') + tx(150, 160, 'dBm + dB = dBm · nunca dBm + dBm')),
    // La potencia se reparte sobre esferas
    sphere: sv(175, `<circle cx="30" cy="65" r="6" fill="var(--led)"/>` + [40, 80, 160].map((r, i) => `<path d="M${(30 + r * Math.cos(-0.36)).toFixed(1)} ${(65 + r * Math.sin(-0.36)).toFixed(1)}A${r} ${r} 0 0 1 ${(30 + r * Math.cos(0.36)).toFixed(1)} ${(65 + r * Math.sin(0.36)).toFixed(1)}" fill="none" stroke="var(--ice)" stroke-width="${3 - i * 0.7}" class="a-fade a-d${i + 1}"/>` + tx(30 + r, 132, ['d', '2d', '4d'][i], 'vizlab')).join('') +
      tx(250, 50, 'superficie', 'vizsm') + tx(250, 66, '×4 cada vez', 'vizsm') + tx(150, 152, 'Doble de distancia: ¼ de potencia = −6 dB', 'vizlab', 'middle', 'fill:var(--led)') + tx(150, 170, '×10 de distancia: −20 dB')),
