  /* ===================== CONCEPTOS =====================
     Cada concepto es una destreza estrecha: todas sus alternativas explican lo mismo desde otro ángulo
     (analogía, números paso a paso, dibujo o visualización, error típico) y su pregunta de comprobación
     practica esa misma destreza. Ninguna alternativa se apoya en algo que se enseñe más tarde. */
  Object.assign(CONCEPTS, {
    /* --- Ondas y propagación --- */
    rf_emwave: { name: 'Qué es una onda de radio', alts: [
      { title: 'Campos que se empujan', text: 'Una corriente que <b>cambia</b> crea un campo magnético que cambia, y este un campo eléctrico que cambia: los dos se sostienen y se alejan de la antena a la velocidad de la luz. Una corriente continua solo crea un campo fijo, que no se aleja.\nLa luz, la radio y los rayos X son esa misma onda; solo cambia la frecuencia.', svg: SVG.emwave, q: mcq('Por un hilo pasa una corriente continua constante de 1 A. ¿Emite ondas de radio?', ['No: un campo que no cambia no se propaga', 'Sí, más que con alterna', 'Sí, pero solo de noche', 'Solo si el hilo es muy largo'], 'Para radiar hace falta que la corriente cambie.') },
      { title: 'Míralo salir de la antena', text: 'Cambia la corriente de la antena entre continua y alterna. Con continua el campo se queda pegado al hilo; con alterna, cada cambio lanza un “frente” que se aleja y no vuelve.', tune: { viz: 'rf_emit', params: { ac: P.emitAC(0), d: fx(30) } }, q: mcq('¿Qué necesita una antena para emitir ondas de radio?', ['Una corriente que cambie, como la alterna', 'Una corriente continua muy grande', 'Un imán potente', 'Estar al aire libre'], 'Solo los campos que cambian se propagan.') },
      { title: 'Una sola familia', text: 'Radio, microondas, infrarrojo, luz visible y rayos X son <b>radiación electromagnética</b>: viajan igual de rápido, también por el vacío, sin necesitar aire. Lo único que las distingue es la <b>frecuencia</b>. Y todas nacen de cargas que oscilan.', q: mcq('¿Qué tienen en común el WiFi y la luz de una bombilla?', ['Son la misma clase de onda electromagnética, con distinta frecuencia', 'Nada: el WiFi es una forma de sonido', 'Los dos necesitan aire para viajar', 'Nada: la luz es mucho más rápida'], 'Misma naturaleza y misma velocidad; distinta frecuencia.') }
    ] },
    rf_speed: { name: 'Tiempo de propagación (t = d / c)', alts: [
      { title: 'Trescientos mil por segundo', text: 'La onda viaja a <b>c ≈ 300 000 km/s</b>. Para saber cuánto tarda: <b>t = d / c</b>. 300 km tardan 1 ms; los unos 20 200 km de un satélite GPS, unos 67 ms.', q: mcq('¿Cuánto tarda una señal de radio en recorrer 3000 km?', ['10 ms', '1 ms', '100 ms', '1 s'], '3000 / 300 000 = 0,01 s.') },
      { title: 'La regla de los 30 cm', text: 'Memoriza una cifra: la luz recorre <b>30 cm por nanosegundo</b>. De ahí sale todo: 1 µs son 300 m y 1 ms son 300 km. Por eso medir distancias con radio exige relojes muy precisos: 10 ns de error son 3 m.', q: mcq('El reloj de un receptor se equivoca 100 ns. ¿Qué error de distancia supone?', ['30 m', '3 m', '300 m', '0,3 m'], '0,3 m/ns × 100 ns = 30 m.') },
      { title: 'Aleja el receptor', text: 'Pon la antena en alterna y mueve el receptor: cada vez que multiplicas la distancia por 10, el retraso se multiplica por 10. Prueba con la Luna (384 400 km).', tune: { viz: 'rf_emit', params: { ac: fx(1), d: P.emitD(300) } }, q: mcq('La Luna está a unos 384 000 km. ¿Cuánto tarda en llegar una señal de radio?', ['Algo más de 1 s', 'Unos 13 ms', 'Unos 2 min', 'Nada: es instantánea'], '384 000 / 300 000 ≈ 1,28 s.') }
    ] },
    rf_wave: { name: 'Longitud de onda (λ = c / f)', alts: [
      { title: 'Lo que avanza en un ciclo', text: 'Mientras la antena hace un ciclo completo, la onda avanza una distancia fija: la <b>longitud de onda λ</b>.\n<b>λ = c / f</b>. Atajo de bolsillo: <b>λ (m) = 300 / f (MHz)</b>.', q: mcq('¿Qué longitud de onda tiene una señal de 100 MHz?', ['3 m', '30 m', '0,3 m', '300 m'], '300 / 100 = 3 m.') },
      { title: 'Proporción inversa', text: 'La velocidad es fija: si la antena oscila el doble de rápido, en cada ciclo la onda avanza la mitad. <b>Doble de frecuencia, mitad de longitud de onda</b>. Por eso las antenas de WiFi son diminutas y las de onda media, enormes.', tune: { viz: 'rf_lambda', params: { f: pF(100), k: fx(0.95) } }, q: mcq('A 433 MHz, λ ≈ 69 cm. ¿Cuánto mide λ a 866 MHz?', ['Unos 35 cm', 'Unos 138 cm', 'Unos 69 cm', 'Unos 17 cm'], 'El doble de frecuencia, la mitad de λ.') },
      { title: 'Cuidado con los prefijos', text: 'El error típico está en las unidades. Con <b>f en MHz, 300 / f da metros</b>: 13,56 MHz → 22 m. Si la frecuencia viene en GHz, pásala antes a MHz: 2,44 GHz = 2440 MHz → 0,123 m = 12,3 cm. Si te sale una antena de WiFi de 120 m, revisa los prefijos.', q: mcq('¿Qué longitud de onda tiene una señal de 5,8 GHz?', ['Unos 5,2 cm', 'Unos 52 m', 'Unos 5,2 mm', 'Unos 52 cm'], '5,8 GHz = 5800 MHz → 300 / 5800 ≈ 0,052 m.') }
    ] },
    rf_polar: { name: 'Polarización', alts: [
      { title: 'La orientación del campo', text: 'La <b>polarización</b> es la orientación del campo eléctrico: una antena vertical emite con polarización vertical. Si la receptora está cruzada (horizontal), capta muy poco: en la práctica, unos 20 dB menos. Con antenas lineales, emisor y receptor se colocan <b>igual</b>.', q: mcq('El emisor tiene la antena horizontal. ¿Cómo pones la del receptor?', ['También horizontal', 'Vertical', 'Da igual', 'Apuntando al suelo'], 'Polarizaciones iguales; cruzadas pierden muchos dB.') },
      { title: 'Gira la antena', text: 'Gira la antena receptora: a 45° pierdes unos 3 dB (la mitad), y cruzada a 90° casi todo. Prueba también una antena circular: pierde 3 dB, pero siempre los mismos, la gires como la gires.', tune: { viz: 'rf_pol', params: { ang: { label: 'Giro del receptor', val: 0, min: 0, max: 90, step: 5, unit: '°', dec: 0 }, circ: { label: 'Receptor: 0 lineal · 1 circular', val: 0, list: [0, 1], dec: 0 } } }, q: mcq('Dos antenas lineales giradas 45° entre sí. ¿Cuánto se pierde por polarización?', ['Unos 3 dB', 'Nada', 'Unos 20 dB', 'Toda la señal'], 'cos² 45° = 0,5: la mitad de la potencia.') },
      { title: 'Lineal y circular', text: 'Hay polarización <b>lineal</b> (vertical u horizontal) y <b>circular</b> (el campo gira). Entre dos lineales cruzadas se pierde muchísimo; entre una lineal y una circular se pierden solo 3 dB, giren como giren. Por eso los satélites, que cambian de orientación, usan circular.', q: mcq('Recibes un satélite de polarización circular con un dipolo. ¿Cuánto pierdes por polarización?', ['Unos 3 dB, se oriente como se oriente', 'Unos 20 dB', 'Nada', 'Toda la señal'], 'Lineal frente a circular: la mitad de la potencia.') }
    ] },
    rf_bands: { name: 'Bandas del espectro (LF … SHF)', alts: [
      { title: 'Décadas con nombre', text: 'El espectro se corta por décadas: <b>LF</b> 30–300 kHz · <b>MF</b> 0,3–3 MHz · <b>HF</b> 3–30 MHz · <b>VHF</b> 30–300 MHz · <b>UHF</b> 0,3–3 GHz · <b>SHF</b> 3–30 GHz. Para clasificar una frecuencia, mira entre qué límites cae: 1575 MHz está entre 300 y 3000 MHz → UHF.', svg: SVG.bands, q: mcq('¿En qué banda está la radio FM (unos 100 MHz)?', ['VHF', 'UHF', 'HF', 'MF'], 'Entre 30 y 300 MHz.') },
      { title: 'Un mapa con chinchetas', text: 'Asocia cada banda con algo que conoces:\n· LF: RFID de 125 kHz. · MF: onda media (≈ 1 MHz).\n· HF: onda corta y NFC (13,56 MHz). · VHF: FM (88–108 MHz) y aviación.\n· UHF: TDT, 433 y 868 MHz, GPS y WiFi de 2,4 GHz. · SHF: WiFi de 5 GHz.', q: mcq('¿Qué uso típico tiene la banda LF?', ['RFID de 125 kHz', 'WiFi', 'Radio FM', 'GPS'], '125 kHz cae entre 30 y 300 kHz.') },
      { title: 'El truco del 3', text: 'Todos los límites empiezan por <b>3</b>: 30 kHz, 300 kHz, 3 MHz, 30 MHz, 300 MHz, 3 GHz… Pasa la frecuencia a MHz y busca entre qué dos “treses” está. 13,56 MHz → entre 3 y 30 → HF. 433 MHz → entre 300 y 3000 → UHF.', q: mcq('¿En qué banda cae 27 MHz?', ['HF', 'VHF', 'MF', 'UHF'], 'Entre 3 y 30 MHz.') }
    ] },
    rf_bandtrade: { name: 'Frecuencias bajas frente a altas', alts: [
      { title: 'Lo que da y lo que quita', text: '<b>Bajas</b>: antenas enormes y poco ancho de banda, pero atraviesan bien paredes y vegetación.\n<b>Altas</b>: antenas pequeñas y <b>mucho ancho de banda</b> (más datos), pero piden visión directa y sufren <b>más atenuación</b> en paredes, lluvia y cuerpos.', svg: SVG.trade, q: mcq('Necesitas transmitir vídeo en alta definición. ¿Qué zona del espectro te conviene?', ['Frecuencias altas: hay mucho ancho de banda', 'Onda media: llega lejos', 'LF: atraviesa mejor', 'Da igual'], 'Más datos exige más ancho de banda, y eso abunda arriba.') },
      { title: 'Cuestión de porcentajes', text: 'Un canal ocupa una fracción de su frecuencia: el 1 % de 1 MHz son 10 kHz (un poco de audio); el 1 % de 5 GHz son 50 MHz (mucho vídeo). Por eso los datos rápidos suben de frecuencia. El precio: a más frecuencia, casi todos los materiales absorben más.', q: mcq('El WiFi de 5 GHz llega peor a la habitación del fondo que el de 2,4 GHz. ¿Por qué?', ['Las paredes atenúan más a más frecuencia', 'Siempre emite con menos potencia', 'Usa otra polarización', 'Porque es más moderno'], 'Más frecuencia, más pérdidas en obstáculos.') }
    ] },
    rf_antsize: { name: 'Tamaño de una antena (λ/2 y λ/4)', alts: [
      { title: 'Fracciones de λ', text: 'El <b>dipolo</b> mide unos λ/2: dos brazos de λ/4. El <b>monopolo</b> es medio dipolo, de λ/4, y la otra mitad la pone un plano de tierra. Primero calcula λ = 300 / f (MHz) y luego divide. En la práctica se cortan algo más cortos que la teoría (factor ≈ 0,95).', q: mcq('¿Cuánto mide, en teoría, un cuarto de onda a 868 MHz?', ['Unos 8,6 cm', 'Unos 34,5 cm', 'Unos 17,3 cm', 'Unos 4,3 cm'], 'λ = 300 / 868 ≈ 34,5 cm → /4 ≈ 8,6 cm.') },
      { title: 'Atajos en MHz', text: 'Con f en MHz: <b>λ/4 (cm) ≈ 7500 / f</b> y <b>λ/2 (cm) ≈ 15 000 / f</b>. 145 MHz → 52 cm; 433 MHz → 17,3 cm; 868 MHz → 8,6 cm. Al revés, un dipolo de 1 m (100 cm) resuena en 15 000 / 100 = 150 MHz.', q: mcq('¿Cuánto mide un dipolo de media onda completo para 300 MHz?', ['50 cm', '25 cm', '1 m', '2 m'], '15 000 / 300 = 50 cm.') },
      { title: 'Mírala crecer', text: 'Mueve la frecuencia: al bajarla, λ y las antenas crecen en la misma proporción. Fíjate en que λ/4 siempre es la mitad de λ/2, y en que el factor de acortamiento recorta un poco la longitud práctica.', tune: { viz: 'rf_lambda', params: { f: pF(145), k: pK() } }, q: mcq('A 145 MHz el cuarto de onda mide unos 52 cm. ¿Y a 435 MHz (el triple)?', ['Unos 17 cm', 'Unos 156 cm', 'Unos 52 cm', 'Unos 26 cm'], 'Triple de frecuencia, un tercio de longitud.') }
    ] },
    rf_trim: { name: 'Ajustar la longitud de una antena', alts: [
      { title: 'Cortar largo, recortar midiendo', text: 'Una antena más larga resuena más abajo; una más corta, más arriba. Como la resonancia real cae algo por debajo de la teoría, se corta <b>un poco larga</b> y se recorta midiendo: recortar es fácil, alargar no.', q: mcq('Tu monopolo resuena en 410 MHz y lo quieres en 433 MHz. ¿Qué haces?', ['Recortarlo un poco', 'Alargarlo', 'Cambiar el cable', 'Subir la potencia'], 'Resuena bajo → está largo → recorta.') },
      { title: 'Recórtala tú', text: 'Mueve la longitud y mira dónde cae el mínimo de la curva (la resonancia). Si está a la izquierda del objetivo, la antena es larga: acórtala. Busca ROE por debajo de 1,5 en la frecuencia objetivo.', tune: { viz: 'rf_trim', params: { len: { label: 'Longitud', val: 9.5, min: 6, max: 20, step: 0.1, unit: 'cm', dec: 1 }, ft: fx(868) } }, q: mcq('El mínimo de ROE cae en 820 MHz y quieres 868 MHz. La antena está…', ['Larga: hay que recortarla', 'Corta: hay que alargarla', 'Perfecta', 'Rota'], 'Resonancia por debajo del objetivo = antena larga.') },
      { title: 'La regla de tres', text: 'La longitud es inversamente proporcional a la frecuencia: <b>L nueva = L actual × f medida / f deseada</b>. Ejemplo: 9,0 cm que resuenan en 830 MHz, para 868 MHz: 9,0 × 830 / 868 ≈ 8,6 cm. Recorta en dos o tres pasos y vuelve a medir.', q: mcq('Un dipolo de 34 cm resuena en 420 MHz. ¿Qué longitud tendrá para 440 MHz?', ['Unos 32,5 cm', 'Unos 35,6 cm', 'Unos 34 cm', 'Unos 30 cm'], '34 × 420 / 440 ≈ 32,5 cm.') }
    ] },
    rf_prop: { name: 'Caminos de propagación', alts: [
      { title: 'Cada banda, su camino', text: '· <b>LF y MF</b>: onda de tierra que sigue la curvatura (cientos de km).\n· <b>HF</b>: rebota en la ionosfera (de un continente a otro).\n· <b>VHF y más</b>: visión directa hasta el horizonte (FM, TDT, GPS desde el espacio).', q: mcq('¿Qué banda usarías para hablar con otro país sin satélites ni repetidores?', ['HF (onda corta)', 'UHF (433 MHz)', 'Microondas (5,8 GHz)', 'Da igual'], 'La HF se refleja en la ionosfera.') },
      { title: 'Prueba frecuencias y horas', text: 'Cambia la frecuencia y pasa del día a la noche. Fíjate en la capa D: de día se traga la onda media; de noche desaparece y la onda media rebota y llega lejísimos.', tune: { viz: 'rf_prop', params: { f: P.propF(1), night: P.night(0) } }, q: mcq('¿Qué camino sigue una señal de 868 MHz?', ['Visión directa, hasta el horizonte', 'Rebote en la ionosfera', 'Onda de tierra de miles de km', 'Ninguno'], 'Por encima de unos 30 MHz manda la visión directa.') },
      { title: 'La ionosfera sigue al Sol', text: 'El Sol ioniza capas altas de la atmósfera. De día, la capa baja (D) absorbe la onda media; de noche desaparece y la señal rebota más arriba: oyes emisoras lejanas. En verano, nubes ionizadas esporádicas o conductos en la troposfera llevan a veces la FM a más de 1000 km.', q: mcq('¿Por qué la onda media llega mucho más lejos de noche?', ['Desaparece la capa D que de día la absorbe', 'Las emisoras suben la potencia', 'El aire está más frío', 'Hay menos tráfico de radio'], 'Sin la capa D, la señal rebota en capas más altas.') }
    ] },
    rf_horizon: { name: 'Horizonte radio (4,12·√h)', alts: [
      { title: 'La fórmula', text: 'Por encima de unos 30 MHz la onda va casi en línea recta, y la Tierra es curva. Con la refracción normal de la atmósfera, una antena a h metros ve hasta <b>d ≈ 4,12·√h km</b>. Entre dos antenas, los horizontes se suman: <b>4,12·(√h₁ + √h₂)</b>.', q: mcq('Una antena a 25 m y otra a 4 m. ¿Horizonte radio?', ['Unos 29 km', 'Unos 12 km', 'Unos 120 km', 'Unos 4 km'], '4,12 × (5 + 2) ≈ 28,8 km.') },
      { title: 'Sube las antenas', text: 'Mueve las alturas y mira dónde se tocan las dos líneas: es el horizonte común. Fíjate en que cuadruplicar una altura solo duplica su parte.', tune: { viz: 'rf_horiz', params: { h1: P.hgt('Antena 1', 4), h2: P.hgt('Antena 2', 4) } }, q: mcq('Subes tu antena de 4 m a 16 m. ¿Qué le pasa a su horizonte?', ['Se duplica', 'Se cuadruplica', 'No cambia', 'Se reduce'], '√16 / √4 = 2.') },
      { title: 'La raíz manda', text: 'Una antena a 9 m ve unos 12 km; un avión a 10 000 m, unos 412 km. Si tu antena del tejado oye un avión a 400 km es porque él está altísimo: su √h pone casi toda la distancia.', q: mcq('¿Horizonte radio de una antena a 100 m de altura?', ['Unos 41 km', 'Unos 412 km', 'Unos 4 km', 'Unos 100 km'], '4,12 × √100 = 41,2 km.') }
    ] },
    rf_fresnel: { name: 'Zona de Fresnel', alts: [
      { title: 'El balón de rugby', text: 'La energía no viaja por una línea fina: ocupa un volumen con forma de balón de rugby alrededor de la línea de visión, la <b>primera zona de Fresnel</b>. Si el suelo o un obstáculo invaden más del 40 % de su radio, se pierde señal aunque “veas” la otra antena.', q: mcq('A 2 km y 868 MHz, el radio de Fresnel en el centro es unos 13 m. Tus antenas están a 1,5 m sobre un campo llano. ¿Qué pasa?', ['El suelo invade la zona de Fresnel y pierdes bastante señal', 'Nada, hay visión directa', 'La señal mejora por el reflejo', 'La onda rodea el suelo sin pérdidas'], 'El alcance a ras de suelo es mucho menor que entre tejados.') },
      { title: 'La cuenta', text: 'Radio en el punto medio: <b>r ≈ 8,66·√(d / f)</b> metros, con d en km y f en GHz. Despeja al menos el <b>60 %</b> de r por encima de cualquier obstáculo. Ejemplo: 5 km a 868 MHz → r ≈ 20,8 m; necesitas unos 12,5 m libres sobre el obstáculo.', tune: { viz: 'rf_fresnel', params: FRES }, q: mcq('Enlace de 4 km a 1 GHz. ¿Radio de Fresnel en el centro?', ['Unos 17 m', 'Unos 35 m', 'Unos 4 m', 'Unos 1,7 m'], '8,66 × √4 ≈ 17,3 m.') }
    ] },
    rf_multipath: { name: 'Multitrayecto y desvanecimiento', alts: [
      { title: 'Ecos que se suman', text: 'Al receptor llegan la onda directa y reflejos (paredes, suelo, coches) con retrasos distintos. Se suman en fase o en contrafase: basta mover el receptor <b>media longitud de onda</b> para pasar de un máximo a un nulo de hasta 20 dB. A 2,44 GHz (λ ≈ 12,3 cm) eso son unos 6 cm.', q: mcq('¿Cada cuánto se repiten los nulos de multitrayecto a 868 MHz (λ ≈ 34,5 cm)?', ['Unos 17 cm', 'Unos 34,5 cm', 'Unos 8,6 cm', 'Unos 3,5 m'], 'Media longitud de onda.') },
      { title: 'Mueve el receptor', text: 'Desliza el receptor y mira cómo el nivel sube y baja: es la suma de la onda directa y la que rebota en la pared. Baja la fuerza del reflejo y verás que los nulos dejan de ser tan profundos.', tune: { viz: 'rf_mpath', params: { x: { label: 'Posición del receptor', val: 3, min: 0, max: 40, step: 0.5, unit: 'cm', dec: 1 }, f: fx(2440), r: { label: 'Fuerza del reflejo', val: 0.9, min: 0, max: 0.95, step: 0.05, dec: 2 } } }, q: mcq('Mueves el receptor unos centímetros y la señal cae 15 dB. ¿Qué ha pasado?', ['Has caído en un nulo donde directa y reflejo se restan', 'Te has alejado mucho', 'El emisor ha bajado la potencia', 'Ha cambiado la polarización'], 'El multitrayecto crea máximos y nulos cada media λ.') },
      { title: 'Todo lo que se mueve cuenta', text: 'Si una persona camina por la habitación cambian los reflejos, y el nivel de un receptor quieto sube y baja. El remedio es la <b>diversidad</b>: dos antenas separadas (más de media λ) rara vez caen en un nulo a la vez, y el receptor usa la mejor.', q: mcq('¿Por qué un router con dos antenas separadas sufre menos cortes?', ['Es raro que las dos estén en un nulo a la vez', 'Transmite el doble de potencia', 'Usa dos bandas a la vez', 'Sus antenas son más largas'], 'Diversidad de antena.') }
    ] },
    rf_obstacle: { name: 'Obstáculos y atenuación', alts: [
      { title: 'Cada obstáculo resta dB', text: 'Una pared de ladrillo puede restar 5–15 dB; hormigón armado o metal, mucho más; una caja metálica cerrada, casi todo (jaula de Faraday). El agua absorbe mucho a 2,4 GHz, y el cuerpo humano es casi todo agua. Las cifras varían muchísimo: mídelas.', svg: SVG.obstacles, q: mcq('Metes un sensor de 868 MHz en una caja de aluminio cerrada. ¿Qué esperas?', ['Que casi no salga señal', 'Más alcance por el reflejo', 'Lo mismo', 'Que transmita en otra frecuencia'], 'El metal cerrado bloquea la RF.') },
      { title: 'Restar de lo previsto', text: 'La fórmula de espacio libre te dice lo que llegaría sin nada en medio. Cada obstáculo resta sus dB a esa cifra. Si mides 15–20 dB menos de lo previsto, sospecha de obstáculos o de la zona de Fresnel invadida, no de la fórmula.', q: mcq('El espacio libre predice −105 dBm y mides −122 dBm. ¿Qué es lo más probable?', ['Obstáculos en el camino: 17 dB de pérdidas extra', 'Que la fórmula de espacio libre esté mal', 'Que el receptor mida de más', 'Que la señal llegue mejor de lo previsto'], 'La realidad casi siempre pierde más que el espacio libre.') }
    ] },

    /* --- Ley y seguridad --- */
    rf_legal: { name: 'Quién regula el espectro', alts: [
      { title: 'Carreteras con normas', text: 'El espectro es un recurso público y compartido. Cada tramo tiene uso asignado y condiciones, que en España recoge el <b>CNAF</b> y vigila la inspección de telecomunicaciones del Estado. En las bandas de <b>uso común</b> no pides licencia ni pagas, pero <b>no tienes protección</b>: aceptas las interferencias de otros equipos legales y no debes causarlas.', q: mcq('Tu sensor de 433 MHz recibe interferencias del mando legal de un vecino. ¿Qué puedes exigir?', ['Nada: en uso común se aceptan las interferencias', 'Que lo retire', 'Que la administración le multe', 'Subir tu potencia sin límite'], 'Es el precio de no necesitar licencia.') },
      { title: 'Quién decide', text: 'Por capas, de lo general a lo concreto: la <b>UIT</b> reparte el espectro mundial; la <b>CEPT</b> armoniza en Europa (ERC 70-03 para dispositivos de corto alcance); la <b>UE</b> fija decisiones y exige el marcado CE (Directiva RED); y <b>España</b> lo concreta en el CNAF. Consulta siempre la versión vigente.', svg: SVG.legal, q: mcq('¿Dónde se recoge, en España, qué servicio usa cada frecuencia y con qué condiciones?', ['En el CNAF y sus notas nacionales', 'En la caja del aparato', 'Solo en el Reglamento de la UIT', 'En un foro de radio'], 'El CNAF concreta lo que deciden UIT, CEPT y UE.') }
    ] },
    rf_eirp: { name: 'Potencia radiada (PIRE y PRA)', alts: [
      { title: 'El límite está en el aire', text: 'Los límites legales son de potencia <b>radiada</b>, no de la que sale del chip: <b>PIRE = potencia − cables + ganancia de la antena (dBi)</b>. Una antena de más ganancia o un amplificador te sacan del límite aunque el módulo esté certificado. La ganancia de la antena <b>receptora</b>, en cambio, no se emite.', q: mcq('Módulo de 14 dBm, sin pérdidas, con antena de 6 dBi. ¿PIRE?', ['20 dBm', '14 dBm', '8 dBm', '84 dBm'], '14 + 6 = 20 dBm.') },
      { title: 'Súbela y bájala', text: 'Mueve la potencia, el cable y la antena. La barra de la derecha es lo que de verdad sale al aire. Cambiar a una antena de más ganancia sube la PIRE igual que subir la potencia del módulo.', tune: { viz: 'rf_eirp', params: { Pt: { label: 'Potencia del módulo', val: 14, min: 0, max: 30, step: 1, unit: 'dBm', dec: 0 }, len: { label: 'Cable', val: 1, list: [0, 0.5, 1, 2, 5, 10], unit: 'm', dec: 1 }, lpm: fx(0.5), G: { label: 'Antena', val: 2.15, list: [-2, 0, 2.15, 3, 5, 6, 9, 12], unit: 'dBi', dec: 2 } } }, q: mcq('20 dBm en el módulo, 1 dB de cable y antena de 9 dBi. ¿PIRE?', ['28 dBm', '30 dBm', '20 dBm', '12 dBm'], '20 − 1 + 9 = 28 dBm.') },
      { title: 'Dos referencias', text: '<b>dBi</b> se mide respecto a una antena isotrópica ideal; <b>dBd</b>, respecto a un dipolo, que tiene 2,15 dBi. Por eso <b>PIRE = PRA + 2,15 dB</b>. 25 mW PRA son 14 dBm PRA = 16,15 dBm PIRE.', q: mcq('Un límite de 10 mW PRA (10 dBm). ¿Cuánto es en PIRE?', ['12,15 dBm', '10 dBm', '7,85 dBm', '20 dBm'], 'PIRE = PRA + 2,15 dB.') }
    ] },
    rf_duty: { name: 'Ciclo de trabajo', alts: [
      { title: 'Segundos por hora', text: 'El <b>ciclo de trabajo</b> es el porcentaje del tiempo que puedes transmitir, medido sobre una hora: 1 % = 36 s; 0,1 % = 3,6 s; 10 % = 360 s.\nPaquetes por hora = segundos permitidos / duración de cada envío (con todas sus repeticiones).', q: mcq('Un paquete tarda 100 ms y la sub-banda permite un 1 %. ¿Cuántos paquetes por hora, como mucho?', ['360', '36', '3600', '10'], '36 s / 0,1 s = 360.') },
      { title: 'Llena la hora', text: 'Cambia la duración del paquete y el porcentaje permitido. La barra es la hora entera; lo naranja, lo que puedes transmitir. Fíjate en cómo los paquetes largos se comen el cupo enseguida.', tune: { viz: 'rf_duty', params: { ms: { label: 'Duración del paquete', val: 370, list: [20, 56, 100, 185, 370, 740, 1320, 2470], unit: 'ms', dec: 0 }, dc: { label: 'Ciclo de trabajo', val: 1, list: [0.1, 1, 10], unit: '%', dec: 1 } } }, q: mcq('Con un 0,1 % de ciclo y envíos de 1 s, ¿cuántos por hora?', ['3', '36', '360', '1'], '3,6 s / 1 s = 3,6 → 3 envíos completos.') },
      { title: 'Elegir sub-banda', text: 'En 868 MHz cada sub-banda tiene su ciclo: 868,0–868,6 MHz con 1 %, 868,7–869,2 MHz con 0,1 % y 869,4–869,65 MHz con 10 %. Si necesitas mucho tiempo de aire, la de 10 % te da cien veces más que la de 0,1 %.', q: mcq('¿Qué sub-banda te deja transmitir más tiempo cada hora?', ['869,4–869,65 MHz, con un 10 %', '868,0–868,6 MHz, con un 1 %', '868,7–869,2 MHz, con un 0,1 %', 'Todas igual'], '10 % = 360 s por hora.') }
    ] },
    rf_srd: { name: 'Bandas de uso común en Europa', alts: [
      { title: 'La tabla de bolsillo', text: '· 433,05–434,79 MHz: 10 mW PRA, ciclo limitado.\n· 868,0–868,6 MHz: 25 mW PRA y 1 %. · 869,4–869,65 MHz: 500 mW PRA y 10 %.\n· 2400–2483,5 MHz: 100 mW PIRE.\n· PMR446: walkies de 0,5 W PRA, con antena fija y sin modificar.\nComprueba siempre la norma vigente.', svg: SVG.srd, q: mcq('¿Qué condición tiene la sub-banda 868,0–868,6 MHz?', ['25 mW PRA y 1 % de ciclo', '500 mW PRA y 10 %', '100 mW PIRE sin ciclo', 'Ninguna'], 'Es la más usada por los sensores de 868 MHz.') },
      { title: 'Uso libre, equipo intacto', text: 'Que una banda sea de uso común significa que el <b>equipo</b> cumple unas condiciones de potencia, antena y ciclo. Si cambias la antena de un walkie PMR446 o le subes la potencia, deja de ser legal aunque la frecuencia sea la misma.', q: mcq('Un walkie PMR446 con antena fija. ¿Qué cambio es legal?', ['Ninguno: se usa tal como viene', 'Una antena exterior', 'Un amplificador de 5 W', 'Usarlo en 868 MHz'], 'La exención de licencia exige el equipo sin modificar.') }
    ] },
    rf_ham: { name: 'Radioaficionados y licencia', alts: [
      { title: 'Un servicio para aprender', text: 'El servicio de aficionados sirve para la autoformación, la experimentación y la intercomunicación, <b>sin ánimo de lucro</b>. Para transmitir en sus bandas (2 m, 70 cm, HF…) hay que aprobar un examen y tener autorización con <b>indicativo</b>. Escuchar, en cambio, es libre.', q: mcq('Quieres hablar por un repetidor de 70 cm (430–440 MHz). ¿Qué te hace falta?', ['Licencia de radioaficionado con indicativo', 'Nada: es banda libre', 'Un equipo con marcado CE', 'Permiso del ayuntamiento'], 'Es banda de aficionados, no de uso común.') },
      { title: 'Escuchar sí, transmitir con licencia', text: 'Regla rápida: <b>recibir</b> emisiones públicas es libre; <b>transmitir</b> fuera de las bandas de uso común exige licencia; y hay cosas prohibidas para todos, como los inhibidores.', svg: SVG.hamgrid, q: mcq('¿Qué actividad no necesita ninguna licencia?', ['Escuchar a radioaficionados con un receptor', 'Transmitir en 144 MHz', 'Contestar por un repetidor de 2 m', 'Emitir con 10 W en 7 MHz'], 'Escuchar emisiones de aficionados es libre.') }
    ] },
    rf_ethics: { name: 'Privacidad y usos prohibidos', alts: [
      { title: 'Recibir lo público, respetar lo privado', text: 'Muchas señales se emiten para que cualquiera las reciba: radiodifusión, posición de aviones, aficionados. Las comunicaciones privadas y los datos de otras personas están protegidos: si los captas por casualidad, no los grabas, no los descifras, no los publicas ni los usas.', svg: SVG.hamgrid, q: mcq('Tu receptor decodifica el sensor de presión de neumáticos del coche de un vecino. ¿Qué haces?', ['Nada con esos datos: ni guardarlos ni publicarlos', 'Publicarlos en un mapa', 'Copiar su identificador', 'Avisar a todo el barrio'], 'Pueden identificar a una persona.') },
      { title: 'Lo que nunca se hace', text: '<b>Inhibidores</b>: prohibidos, y no distinguen a quién bloquean (también a emergencias). Interceptar o difundir comunicaciones privadas: lo impide el secreto de las comunicaciones. Leer o clonar tarjetas de acceso, bancarias o documentos de otros: no es tu decisión. Ante la duda, no lo hagas.', q: mcq('Alguien quiere un inhibidor “solo para su casa”. ¿Qué le dices?', ['Que es ilegal: bloquea también a otros, incluidas emergencias', 'Que en casa es legal', 'Que es legal si es pequeño', 'Que solo es ilegal en 2,4 GHz'], 'Ningún tamaño ni lugar lo hace legal.') }
    ] },
    rf_safety: { name: 'Seguridad: dónde está el peligro', alts: [
      { title: 'No es la RF de tus módulos', text: 'Un módulo de unos mW no calienta el cuerpo de forma apreciable: está muy por debajo de los límites de exposición. El peligro real en la radio casera es <b>eléctrico</b>: el condensador y el transformador de alta tensión de un microondas (mortales aunque esté desenchufado), un mástil que cae sobre un cable aéreo o un rayo que entra por la antena.', svg: SVG.danger, q: mcq('¿Qué es lo más peligroso de todo esto?', ['Abrir un microondas o montar un mástil cerca de un cable eléctrico', 'Un módulo de radio de 25 mW', 'Un receptor de radio por USB', 'Un sensor inalámbrico sobre la mesa'], 'La RF de milivatios no es el problema; la alta tensión, sí.') },
      { title: 'Tres reglas de oro', text: '1) Mástiles: distancia a cualquier línea eléctrica mayor que su altura, nunca con viento ni solo.\n2) Tormenta: antenas desconectadas y unidas a la toma de tierra exterior.\n3) Nada de desmontar microondas ni fuentes de alta tensión.\nCon decenas de vatios la RF sí quema: ahí, distancia a la antena.', q: mcq('Se acerca una tormenta y tu antena exterior está conectada al receptor. ¿Qué haces?', ['Desconectarla y unirla a la toma de tierra exterior', 'Subir el volumen', 'Nada: el receptor no tiene pilas', 'Tocar la antena para descargarla'], 'Una descarga cercana induce tensiones enormes.') }
    ] },
    rf_inprot: { name: 'Proteger entradas y salidas de RF', alts: [
      { title: 'Cada puerto aguanta lo suyo', text: 'La entrada de un receptor sensible (un SDR, una radio por USB) o de un analizador de antenas está hecha para señales diminutas: unos pocos mW directos pueden romperla. Para ver un emisor, recíbelo por el aire a distancia o por cable con un <b>atenuador</b>. Y el amplificador de un emisor necesita su antena o una carga de 50 Ω.', svg: SVG.atten, q: mcq('Quieres ver la salida de tu emisor de 100 mW en un receptor SDR por cable. ¿Qué pones en medio?', ['Un atenuador adecuado (40 dB o más)', 'Nada, el cable basta', 'Un amplificador', 'Un filtro de audio'], 'La entrada del receptor no aguanta milivatios.') },
      { title: 'Mira qué hay al otro lado', text: 'Antes de conectar un coaxial, pregúntate: ¿hay un emisor transmitiendo? → atenuador o por el aire. ¿Hay una salida de RF sin antena? → no transmitas. ¿Lleva tensión continua el coaxial (alimentación por el cable)? → solo si lo de enfrente lo admite.', q: mcq('Un módulo de radio va a transmitir y la antena está desconectada. ¿Qué haces?', ['Conectar la antena (o una carga de 50 Ω) antes de alimentarlo', 'Transmitir igual', 'Subir la potencia', 'Acortar el mensaje'], 'Sin carga, la potencia reflejada puede dañar el amplificador.') }
    ] },

    /* --- Decibelios y balance --- */
    rf_db: { name: 'dBm ↔ mW', alts: [
      { title: 'Reglas de bolsillo', text: 'En potencia: <b>+3 dB ≈ ×2</b>, <b>+10 dB = ×10</b>, −3 dB ≈ la mitad, −10 dB = una décima.\n<b>0 dBm = 1 mW</b>. Así, 10 dBm = 10 mW, 20 dBm = 100 mW, 30 dBm = 1 W, y hacia abajo −10 dBm = 0,1 mW y −30 dBm = 1 µW.', q: mcq('¿Cuántos mW son 20 dBm?', ['100 mW', '20 mW', '2 mW', '1 W'], '+10 dB es ×10: 0 → 1 mW, 10 → 10 mW, 20 → 100 mW.') },
      { title: 'La fórmula', text: '<b>dBm = 10 · log₁₀(P / 1 mW)</b> y, al revés, <b>P = 1 mW × 10^(dBm / 10)</b>. Para <b>dBW</b> la referencia es 1 W: dBW = dBm − 30. Ejemplo: −120 dBm = 10⁻¹² mW = 10⁻¹⁵ W.', q: mcq('¿Cuántos dBm son 1 W?', ['30 dBm', '0 dBm', '60 dBm', '3 dBm'], '1 W = 1000 mW → 10 · log(1000) = 30.') },
      { title: 'La regla deslizante', text: 'Mueve la potencia: cada 10 dB la potencia se multiplica por 10 y cada 3 dB se duplica. 0 dBm es 1 mW, los valores negativos son fracciones de mW y 14 dBm son unos 25 mW.', tune: { viz: 'rf_dbm', params: { P: { label: 'Potencia', val: 14, min: -140, max: 80, step: 1, unit: 'dBm', dec: 0 } } }, q: mcq('¿Cuánto son −30 dBm?', ['1 µW', '1 mW', '−30 mW', '0,03 mW'], '−30 dB es ÷1000: 1 mW / 1000 = 1 µW.') }
    ] },
    rf_dbratio: { name: 'Relaciones en dB (×2 = 3 dB)', alts: [
      { title: 'Factores de bolsillo', text: 'Un cambio en dB es una <b>relación</b> de potencias: ×2 = +3 dB, ×4 = +6 dB, ×10 = +10 dB, ×100 = +20 dB; la mitad = −3 dB y una décima = −10 dB. Dos emisores iguales juntos son el doble de potencia: +3 dB, no el doble de dBm.', q: mcq('Juntas dos señales independientes de 0 dBm. ¿Total?', ['Unos 3 dBm', '0 dBm', '6 dBm', '−3 dBm'], '1 mW + 1 mW = 2 mW ≈ 3 dBm.') },
      { title: 'Cuenta cuadraditos', text: 'Mueve los dB y cuenta cuadrados: +3 dB son 2, +6 dB son 4, +10 dB son 10. En negativo, el bloque entero es lo que había y se va vaciando: −3 dB deja la mitad, −10 dB una décima.', tune: { viz: 'rf_dbr', params: { dB: P.dB(0) } }, q: mcq('Una potencia sube 6 dB. ¿Por cuánto se ha multiplicado?', ['Por 4', 'Por 6', 'Por 2', 'Por 60'], '3 dB + 3 dB: ×2 × 2.') },
      { title: 'De dB a fracción', text: 'Para pasar una pérdida a fracción: <b>10^(−dB / 10)</b>. 3 dB → 0,5; 4 dB → 0,4; 10 dB → 0,1; 20 dB → 0,01. Error típico: usar 20·log, que es para tensiones; en potencia, siempre 10·log.', q: mcq('Un cable pierde 6 dB. ¿Qué fracción de la potencia llega?', ['Una cuarta parte', 'La mitad', 'Un 6 %', 'Un 94 %'], '10^(−0,6) ≈ 0,25.') }
    ] },
    rf_chain: { name: 'Sumar ganancias y pérdidas en dB', alts: [
      { title: 'Sumar en vez de multiplicar', text: 'En dB, las ganancias se <b>suman</b> y las pérdidas se <b>restan</b>. Un nivel absoluto (dBm) más una ganancia (dB) da otro nivel en dBm. Los cables se dan en dB por metro: multiplica por la longitud. Lo que no tiene sentido es sumar dos dBm entre sí.', svg: SVG.chain, q: mcq('Un emisor de 10 dBm, 3 dB de pérdida en el cable y una antena de 5 dBi. ¿PIRE?', ['12 dBm', '18 dBm', '2 dBm', '150 dBm'], '10 − 3 + 5 = 12 dBm.') },
      { title: 'Paso a paso', text: 'Recorre la cadena desde el emisor: empiezas en dBm y cada bloque suma su ganancia o resta su pérdida. Ejemplo: 20 dBm − 4 dB de cable (8 m × 0,5 dB/m) − 0,4 dB de conectores + 5 dBi = 20,6 dBm.', tune: { viz: 'rf_eirp', params: { Pt: fx(20), len: { label: 'Cable', val: 2, list: [0, 0.5, 1, 2, 5, 10], unit: 'm', dec: 1 }, lpm: { label: 'Pérdida del cable', val: 0.5, list: [0.1, 0.3, 0.5, 1], unit: 'dB/m', dec: 1 }, G: fx(5) } }, q: mcq('17 dBm, 1,5 dB de cable y una antena de 3 dBi. ¿PIRE?', ['18,5 dBm', '21,5 dBm', '15,5 dBm', '76,5 dBm'], '17 − 1,5 + 3 = 18,5 dBm.') }
    ] },
    rf_pathlaw: { name: 'Pérdidas y distancia', alts: [
      { title: 'La esfera que crece', text: 'La potencia emitida se reparte sobre una esfera cada vez mayor: al <b>doblar la distancia</b>, la superficie se multiplica por 4 y llegan <b>6 dB menos</b>; ×10 en distancia son 20 dB. Al revés, 6 dB de pérdidas extra cuestan la mitad del alcance.', svg: SVG.sphere, q: mcq('Duplicas la distancia de un enlace en espacio libre. ¿Cuánto pierdes?', ['6 dB', '3 dB', '12 dB', 'El doble de dB'], 'Inversa del cuadrado: ×¼ en potencia = −6 dB.') },
      { title: 'Aléjate y mira', text: 'Duplica la distancia y fíjate en la barra: siempre +6 dB, estés a 100 m o a 10 km. Multiplícala por 10: +20 dB.', tune: { viz: 'rf_fspl', params: { d: P.dKm(1), f: fx(868) } }, q: mcq('A 1 km pierdes 91 dB. ¿Cuánto pierdes a 4 km en espacio libre?', ['Unos 103 dB', 'Unos 97 dB', 'Unos 364 dB', 'Unos 95 dB'], '×4 = ×2 × 2: +6 + 6 = +12 dB.') },
      { title: 'De dB a distancia y vuelta', text: 'Modelo log-distancia: <b>pérdida extra = 10·n·log₁₀(d₂ / d₁)</b>, con n = 2 en espacio libre (en ciudad o interiores, 3 o más). Al revés, <b>d = 10^(ΔdB / (10·n))</b>: con n = 2, 20 dB son ×10 de distancia y ±6 dB son ×2 o ÷2.', q: mcq('Con n = 2, una señal llega 20 dB más débil que a 1 m. ¿A qué distancia está?', ['10 m', '20 m', '100 m', '2 m'], '10^(20 / 20) = 10.') }
    ] },
    rf_fspl: { name: 'Pérdidas en espacio libre (FSPL)', alts: [
      { title: 'La fórmula práctica', text: '<b>FSPL (dB) = 20·log₁₀(d en km) + 20·log₁₀(f en MHz) + 32,44</b>. Ejemplo: 1 km a 868 MHz → 0 + 58,8 + 32,44 ≈ 91,2 dB. Cada ×10 en distancia o en frecuencia suma 20 dB.', q: mcq('¿FSPL a 10 km y 100 MHz?', ['Unos 92,4 dB', 'Unos 72,4 dB', 'Unos 52,4 dB', 'Unos 132,4 dB'], '20 + 40 + 32,44 = 92,44 dB.') },
      { title: '¿Por qué depende de la frecuencia?', text: 'El aire no “frena” más las frecuencias altas. Lo que pasa es que una antena receptora de la misma ganancia (un dipolo, por ejemplo) es más pequeña a más frecuencia y <b>recoge menos</b>. Mira el círculo verde: al subir la frecuencia, se encoge.', tune: { viz: 'rf_fspl', params: { d: fx(2), f: P.fSub(433.92) } }, q: mcq('Dos enlaces iguales con dipolos, a 433 y a 868 MHz. ¿Cuál pierde más en espacio libre?', ['El de 868 MHz, unos 6 dB más', 'El de 433 MHz', 'Pierden lo mismo', 'El de 868 MHz, el doble de dB'], 'Doble de frecuencia: +20·log(2) ≈ 6 dB.') }
    ] },
    rf_noise: { name: 'Ruido térmico y figura de ruido', alts: [
      { title: 'El murmullo de fondo', text: 'Cualquier resistencia a temperatura ambiente genera ruido: <b>−174 dBm por cada hercio</b> de ancho de banda. Un receptor que escucha 125 kHz recoge 10·log(125 000) ≈ 51 dB más: unos −123 dBm. Encima, el receptor suma su <b>figura de ruido (NF)</b>.', q: mcq('Pasas de 125 kHz a 500 kHz de ancho de banda. El ruido que entra…', ['Sube unos 6 dB', 'Baja 6 dB', 'No cambia', 'Se multiplica por 375'], '×4 en ancho de banda = +6 dB de ruido.') },
      { title: 'Apila los términos', text: 'Mueve el ancho de banda y la figura de ruido: cada línea es un escalón de la cuenta. El suelo de ruido sube 10 dB cada vez que el ancho de banda se multiplica por 10.', tune: { viz: 'rf_noise', params: { bw: P.bw(125), nf: P.nf(6), snr: fx(0) } }, q: mcq('BW = 125 kHz y NF = 6 dB. ¿Suelo de ruido?', ['Unos −117 dBm', 'Unos −168 dBm', 'Unos −123 dBm', 'Unos −63 dBm'], '−174 + 51 + 6 ≈ −117 dBm.') },
      { title: 'El primero manda', text: 'En una cadena, el ruido del <b>primer</b> bloque pesa más que el de los demás. Un cable antes del amplificador de bajo ruido (LNA) suma sus dB de pérdida directamente a la NF. Por eso el LNA va pegado a la antena.', svg: SVG.lna, q: mcq('Tienes 15 m de cable con 5 dB de pérdida hasta el receptor. ¿Dónde pones el LNA?', ['Junto a la antena, antes del cable', 'Junto al receptor', 'En medio', 'Da igual'], 'Si lo pones después, el cable ya ha empeorado 5 dB la figura de ruido.') }
    ] },
    rf_sens: { name: 'Sensibilidad: ancho de banda y SNR', alts: [
      { title: 'La fórmula de la sensibilidad', text: '<b>Sensibilidad = −174 + 10·log(BW) + NF + SNR mínima</b>.\nPara oír señales más débiles: menos ancho de banda (transmitir más lento), menos ruido propio o una modulación que necesite menos SNR (algunas funcionan incluso con SNR negativa).', q: mcq('BW = 1 MHz, NF = 6 dB, SNR mínima 10 dB. ¿Sensibilidad?', ['−98 dBm', '−174 dBm', '−108 dBm', '−158 dBm'], '−174 + 60 + 6 + 10 = −98 dBm.') },
      { title: 'Bájala tú', text: 'Mueve los tres deslizadores y mira la línea naranja. Estrechar el ancho de banda es lo que más baja la sensibilidad: cada ÷10 son 10 dB.', tune: { viz: 'rf_noise', params: { bw: P.bw(1000), nf: P.nf(6), snr: P.snr(10) } }, q: mcq('Pasas un enlace de 10 kbps a 1 kbps con la misma modulación. ¿Qué ganas aproximadamente?', ['Unos 10 dB de sensibilidad', 'Nada', '1 dB', 'Más potencia emitida'], 'Ancho de banda ÷10 → ruido −10 dB.') },
      { title: 'Velocidad contra alcance', text: 'Transmitir más lento permite un filtro más estrecho: entra menos ruido y el receptor oye señales más débiles. Por eso los enlaces lentos llegan más lejos con la misma potencia, y los rápidos necesitan más señal.', q: mcq('¿Por qué un enlace lento llega más lejos que uno rápido con la misma potencia?', ['Su filtro es más estrecho y entra menos ruido', 'Emite más potencia', 'Usa otra frecuencia', 'Su antena es más grande'], 'Menos ancho de banda, menos ruido.') }
    ] },
    rf_lorasnr: { name: 'SNR de LoRa y elección del SF', alts: [
      { title: 'Por debajo del ruido', text: 'LoRa demodula con <b>SNR negativa</b>: hasta unos −7,5 dB con SF7 y −20 dB con SF12. Una SNR de −8 dB significa que la señal llega 8 dB por debajo del ruido y aun así se recibe. Cerca del mínimo de su SF, estás al borde; muy por encima, te sobra margen.', svg: sv(150, tx(150, 18, 'SNR mínima de cada SF (orientativa)', 'vizlab') + [7, 8, 9, 10, 11, 12].map((s, i) => `<rect x="${30 + i * 42}" y="${40}" width="30" height="${(-LORA_SNR[s]) * 4}" fill="var(--ice)" opacity="${0.4 + i * 0.1}"/>` + tx(45 + i * 42, 136, 'SF' + s) + tx(45 + i * 42, 52 + (-LORA_SNR[s]) * 4 - 16, neg(num(LORA_SNR[s], 1)), 'vizsm')).join('') + ln('M20 40H290', 'currentColor', 1) + tx(26, 36, '0 dB', 'vizsm', 'start')), q: mcq('Con SF7 (mínimo ≈ −7,5 dB) recibes paquetes con SNR de −7 dB. ¿Cómo vas?', ['Al borde: casi sin margen', 'Sobrado: puedes bajar el SF', 'Mal: una SNR negativa es imposible', 'Perfecto: cuanto más negativa, mejor'], 'Solo 0,5 dB por encima del mínimo de SF7.') },
      { title: 'Elegir el SF con la SNR', text: 'Compara la SNR de los paquetes con el mínimo de su SF. Si te sobran muchos dB (por ejemplo, SNR positiva con SF12), <b>baja el SF</b>: el paquete dura menos, gastas menos batería y ocupas menos el canal. Si estás al límite, sube el SF o mejora la antena.', q: mcq('Un nodo con SF10 (mínimo ≈ −15 dB) recibe con SNR de +5 dB. ¿Qué harías?', ['Bajar el SF', 'Subir a SF12', 'Subir la potencia', 'Cambiar de banda'], 'Le sobran unos 20 dB.') }
    ] },
    rf_budget: { name: 'Balance de enlace y margen', alts: [
      { title: 'La cuenta de la compra', text: 'Empiezas con la potencia del emisor y vas sumando y restando:\n<b>Pr = Pt − cables + Gt − pérdidas del camino + Gr − cables</b>.\nEl <b>margen</b> es Pr menos la sensibilidad del receptor. Con menos de 10 dB de margen, el enlace irá “a ratos”.', q: mcq('Recibes −112 dBm y la sensibilidad es −120 dBm. ¿Margen?', ['8 dB', '−8 dB', '232 dB', '120 dB'], '−112 − (−120) = 8 dB: justo.') },
      { title: 'La escalera', text: 'Dibuja el nivel de la señal a lo largo del enlace: sube con las antenas y baja con cables y camino. Donde acaba la escalera está Pr; la distancia hasta la línea de sensibilidad es el <b>margen</b>. Orientativo: 10 dB para un enlace fijo con visión directa; 20 dB o más con obstáculos o movimiento.', tune: { viz: 'rf_link', params: LINK }, q: mcq('Pr = −118 dBm y la sensibilidad es −123 dBm. ¿Qué esperas?', ['Un enlace que falla a ratos: solo 5 dB de margen', 'Un enlace perfecto', 'Que no llegue nunca', 'Un margen de 241 dB'], 'Cualquier desvanecimiento se come 5 dB.') }
    ] },

    /* --- Circuitos de RF --- */
    rf_resonance: { name: 'Frecuencia de resonancia LC', alts: [
      { title: 'El columpio', text: 'En un circuito LC la energía va y viene entre el campo eléctrico del condensador y el magnético de la bobina, a un ritmo propio: <b>f₀ = 1 / (2π√(LC))</b>. Cuadruplicar L o C reduce f₀ a la mitad; menos L o menos C, más f₀.', q: mcq('Multiplicas C por 4. La frecuencia de resonancia…', ['Se reduce a la mitad', 'Se duplica', 'Se divide entre 4', 'No cambia'], 'f₀ va con 1/√C: √4 = 2.') },
      { title: 'Muévela', text: 'Cambia L y C y mira dónde queda el pico. Prueba a multiplicar C por 4 (de 100 a 470 pF, aproximadamente) y verás que f₀ cae a la mitad.', tune: { viz: 'rf_lc', params: { L: LCL(10), C: LCC(100), Q: fx(50) } }, q: mcq('L = 10 µH y C = 100 pF resuenan en unos 5 MHz. ¿Qué pasa si pones 10 pF?', ['Sube a unos 16 MHz', 'Baja a unos 1,6 MHz', 'Sube a 50 MHz', 'No cambia'], '÷10 en C → ×√10 ≈ ×3,16 en f₀.') },
      { title: 'Cálculo con prefijos', text: 'Con L en µH y C en pF hay un atajo: <b>f₀ (MHz) ≈ 159 / √(L·C)</b>. Ejemplo: 100 µH y 220 pF → √22 000 ≈ 148 → 159 / 148 ≈ 1,07 MHz. Si lo haces con la fórmula completa, pasa antes a henrios y faradios.', q: mcq('L = 1 µH y C = 100 pF. ¿f₀?', ['Unos 15,9 MHz', 'Unos 1,59 MHz', 'Unos 159 MHz', 'Unos 0,16 MHz'], '159 / √100 = 15,9 MHz.') }
    ] },
    rf_reactance: { name: 'Reactancia en RF (XL y XC)', alts: [
      { title: 'Las fórmulas con números', text: '<b>XL = 2π·f·L</b> crece con la frecuencia; <b>XC = 1 / (2π·f·C)</b> baja. Un centímetro de hilo tiene unos 10 nH: a 868 MHz son unos 54 Ω y a 2,44 GHz unos 153 Ω, tanto o más que la impedancia del sistema. Por eso una protoboard no sirve a GHz.', q: mcq('¿Reactancia de 100 nH a 100 MHz?', ['Unos 63 Ω', 'Unos 6,3 Ω', 'Unos 630 Ω', 'Unos 0,63 Ω'], '2π × 10⁸ × 10⁻⁷ ≈ 62,8 Ω.') },
      { title: 'El condensador que se vuelve bobina', text: 'Un condensador real tiene la inductancia de sus terminales. Mueve la frecuencia: por debajo de su <b>autorresonancia</b> se comporta como condensador; por encima, como bobina. Busca un valor que siga siendo condensador a 2,44 GHz.', tune: { viz: 'rf_capr', params: { C: { label: 'Capacidad', val: 100000, list: [1, 10, 100, 1000, 10000, 100000], unit: 'pF', dec: 0 }, esl: fx(1), f: { label: 'Frecuencia', val: 1, list: [1, 10, 100, 433.92, 868, 2440], unit: 'MHz', dec: 2 } } }, q: mcq('Un 100 nF cerámico desacopla bien a 1 MHz pero no a 2,4 GHz. ¿Por qué?', ['Por encima de su autorresonancia manda su inductancia parásita', 'Porque se descarga', 'Porque es demasiado pequeño', 'Porque la continua no pasa'], 'A GHz domina la inductancia de terminales y encapsulado.') },
      { title: 'Grifos que dependen de la frecuencia', text: 'Una bobina es un grifo abierto para la continua y cada vez más cerrado al subir la frecuencia: así una <b>bobina de choque</b> alimenta un amplificador sin dejar escapar la RF. Un condensador, al revés: bloquea la continua y deja pasar la RF.', q: mcq('¿Qué componente deja pasar la continua de alimentación pero frena la RF?', ['Una bobina de choque', 'Un condensador en serie', 'Una resistencia de 0 Ω', 'Un diodo'], 'XL crece con la frecuencia: casi 0 Ω en continua.') }
    ] },
    rf_skin: { name: 'Efecto pelicular', alts: [
      { title: 'Un tubo hueco', text: 'En continua la corriente usa toda la sección del hilo. A alta frecuencia, los campos de la propia corriente la empujan hacia fuera y solo circula por una <b>capa fina de la superficie</b>. Es como si el hilo fuera un tubo hueco: menos sección útil, más resistencia.', tune: { viz: 'rf_skin', params: { f: { label: 'Frecuencia', val: 0.01, list: [0.01, 0.1, 1, 10, 100, 1000, 2440], unit: 'MHz', dec: 2 }, dmm: fx(1) } }, q: mcq('¿Por qué las bobinas de RF de calidad usan hilo plateado o tubo de cobre?', ['La corriente circula solo por la superficie', 'Por estética', 'Para que pesen menos', 'Para aislar mejor'], 'A RF lo que cuenta es la superficie.') },
      { title: 'Los números', text: 'Profundidad pelicular en cobre ≈ <b>66 µm / √(f en MHz)</b>: 66 µm a 1 MHz, 6,6 µm a 100 MHz y unos 2 µm a 1 GHz. Un hilo de 1 mm de diámetro a 100 MHz solo usa un anillo de pocas micras: su resistencia sube muchísimo respecto a la de continua.', q: mcq('¿Profundidad pelicular del cobre a 100 MHz?', ['Unos 6,6 µm', 'Unos 66 µm', 'Unos 0,66 mm', 'Toda la sección'], '66 / √100 = 6,6 µm.') }
    ] },
    rf_pcb: { name: 'Placas de RF: plano de masa', alts: [
      { title: 'La corriente vuelve por debajo', text: 'En RF, la corriente de retorno va justo por debajo de su pista, en el plano de masa. Si cortas el plano bajo una pista de RF, el retorno da un rodeo: la pista deja de ser de 50 Ω y forma un bucle que radia (y capta). Plano continuo, pistas cortas y vías a masa cerca.', svg: SVG.retpath, q: mcq('Tienes que cruzar una pista de señal bajo la pista de antena de 2,4 GHz. ¿Qué es mejor?', ['Pasarla por otra capa sin cortar el plano bajo la pista de RF', 'Cortar el plano de masa justo debajo', 'Alargar la pista de RF', 'Da igual'], 'El plano bajo la pista de RF debe ser continuo.') },
      { title: 'Bucles pequeños', text: 'Todo bucle por el que circula corriente rápida es una antena: cuanto mayor su área, más radia y más capta. Se reduce con <b>plano de masa</b> continuo, condensadores de desacoplo junto a cada chip y pistas y cables cortos.', q: mcq('¿Qué reduce más el ruido que radia tu propio diseño?', ['Plano de masa, desacoplo junto a los chips y bucles pequeños', 'Cables más largos', 'Pintar la placa', 'Subir la frecuencia del reloj'], 'Menos área de bucle, menos antena.') }
    ] },
    rf_coil: { name: 'Bobinas: vueltas e inductancia', alts: [
      { title: 'La fórmula de Wheeler', text: '<b>L (µH) ≈ d²·N² / (45,7·d + 101,6·l)</b>, con diámetro d y longitud l en cm. Ejemplo: d = 3 cm, N = 40, l = 4 cm → 9 × 1600 / (137,1 + 406,4) ≈ 26,5 µH. Fíjate en N²: quitar vueltas baja L muy deprisa.', svg: SVG.coil, q: mcq('Una bobina con el doble de vueltas y el mismo tamaño. ¿Inductancia?', ['El cuádruple', 'El doble', 'La mitad', 'La misma'], 'L va con N².') },
      { title: 'Enróllala tú', text: 'Cambia vueltas, diámetro y longitud. Duplica las vueltas y mira cómo L se multiplica por 4; estira la bobina (más longitud) y verás que L baja.', tune: { viz: 'rf_coil', params: { dcm: { label: 'Diámetro', val: 3, list: [1, 2, 3, 5, 8], unit: 'cm', dec: 0 }, N: { label: 'Vueltas', val: 20, min: 1, max: 120, step: 1, dec: 0 }, l: { label: 'Longitud', val: 3, min: 0.5, max: 10, step: 0.5, unit: 'cm', dec: 1 } } }, q: mcq('Tu tanque resuena un poco bajo. ¿Qué haces con la bobina?', ['Quitar una vuelta o separar las espiras', 'Añadir vueltas', 'Meter un núcleo de ferrita', 'Cambiar el diodo'], 'Menos L → más f₀.') }
    ] },
    rf_tank: { name: 'LC serie y paralelo en resonancia', alts: [
      { title: 'Dos comportamientos opuestos', text: 'En resonancia las reactancias de L y C se anulan. En <b>serie</b>, queda una impedancia <b>mínima</b> (solo las pérdidas). En <b>paralelo</b> (circuito tanque), la impedancia es <b>máxima</b>: a la entrada de una radio, la frecuencia deseada encuentra alta impedancia y se queda; las demás se van a masa.', svg: SVG.lcSP, q: mcq('Un LC en paralelo, justo en resonancia, presenta…', ['Una impedancia máxima', 'Una impedancia mínima', 'Un cortocircuito', 'Una capacidad pura'], 'En paralelo, en resonancia, impedancia máxima.') },
      { title: 'El atajo y la puerta', text: 'Imagina el LC <b>serie</b> como un atajo que solo existe a f₀: puesto entre señal y masa, se traga esa frecuencia (una trampa). El LC <b>paralelo</b> es una puerta que solo se cierra a f₀: puesto entre antena y masa, deja la emisora sintonizada y manda las demás a masa.', q: mcq('Quieres eliminar una frecuencia molesta desviándola a masa. ¿Qué pones entre la señal y masa?', ['Un LC en serie sintonizado a esa frecuencia', 'Un LC en paralelo sintonizado a esa frecuencia', 'Una resistencia', 'Un diodo'], 'El LC serie es un camino de baja impedancia solo a f₀.') }
    ] },
    rf_q: { name: 'Factor Q y ancho de banda', alts: [
      { title: 'Q es la selectividad', text: 'El <b>factor Q</b> mide lo estrecha que es la resonancia: <b>BW = f₀ / Q</b>. Las pérdidas y todo lo que <b>carga</b> el circuito bajan la Q y ensanchan la curva. Una Q alta separa emisoras cercanas; una baja deja pasar muchas a la vez.', q: mcq('Un circuito resuena a 1 MHz con Q = 50. ¿Ancho de banda?', ['20 kHz', '50 kHz', '50 MHz', '2 kHz'], '1 000 000 / 50 = 20 000 Hz.') },
      { title: 'Con la curva delante', text: 'Sube la Q y mira cómo se estrecha la curva: el ancho de banda a −3 dB es f₀ / Q. Para separar emisoras de onda media a 9 kHz cerca de 1 MHz hace falta Q > 110.', tune: { viz: 'rf_lc', params: { L: LCL(100), C: LCC(220), Q: LCQ(50) } }, q: mcq('Un circuito a 455 kHz con Q = 50. ¿Ancho de banda?', ['9,1 kHz', '22,8 kHz', '0,91 kHz', '91 kHz'], '455 / 50 = 9,1 kHz.') }
    ] },
    rf_harmonics: { name: 'Armónicos', alts: [
      { title: 'Múltiplos enteros', text: 'Un emisor no lineal o una onda cuadrada generan <b>armónicos</b> en 2f, 3f, 4f… El tercero de 433,92 MHz cae en 1301,76 MHz, en bandas de otros servicios. Por eso la salida de un emisor lleva un <b>filtro paso bajo</b>, y nunca se pone antena a un generador de onda cuadrada sin filtrar.', q: mcq('¿Dónde cae el segundo armónico de 868 MHz?', ['1736 MHz', '434 MHz', '870 MHz', '2604 MHz'], '2 × 868 MHz.') },
      { title: 'Míralos y fíltralos', text: 'Elige una onda cuadrada y mira su espectro: rayas en 3f, 5f, 7f… Ahora pon un filtro paso bajo justo por encima de f: los armónicos caen y la fundamental se queda.', tune: { viz: 'rf_harm', params: { w: { label: 'Onda: 1 seno · 2 cuadrada · 3 seno recortado', val: 2, list: [1, 2, 3], dec: 0 }, fc: { label: 'Corte del filtro (× f, 0 = sin filtro)', val: 0, list: [0, 0.7, 1.3, 2, 3, 5], dec: 1 } } }, q: mcq('Un generador da una cuadrada de 7 MHz. ¿Qué frecuencias contiene sobre todo?', ['7, 21, 35 MHz…', 'Solo 7 MHz', '7, 14, 28 MHz…', '3,5 y 7 MHz'], 'Una cuadrada simétrica: armónicos impares.') },
      { title: 'La cuadrada lleva de todo', text: 'Una onda cuadrada es su fundamental más todos sus armónicos impares (3f, 5f, 7f…) con amplitudes 1/3, 1/5, 1/7… Muy lejos de ser “una frecuencia”. Las emisiones fuera de banda tienen límites muy estrictos: filtra antes de radiar.', q: mcq('¿Qué amplitud tiene el tercer armónico de una cuadrada ideal, respecto a la fundamental?', ['Un tercio', 'La mitad', 'Igual', 'Nada'], 'Armónicos impares con amplitud 1/n.') }
    ] },
    rf_filters: { name: 'Elegir un filtro de RF', alts: [
      { title: 'Qué quieres que pase', text: '· <b>Paso bajo</b> a la salida de un emisor: quita armónicos.\n· <b>Paso banda</b> delante de un receptor: solo entra la banda útil.\n· <b>Rechazo de banda</b>: quita una banda molesta, como las emisoras de FM delante de un receptor de 137 MHz.\n· <b>Cerámicos y SAW</b>: flancos abruptos en poco espacio.', svg: sv(150, [['Paso bajo', 'M10 40H60Q75 40 85 110', 0], ['Paso banda', 'M10 110Q30 110 40 40H60Q70 40 85 110', 1], ['Rechazo', 'M10 40H30Q40 40 47 110Q55 40 65 40H85', 2]].map(([n, d, i]) => `<g transform="translate(${10 + i * 95} 10)"><path d="M10 110H90M10 110V30" stroke="var(--muted)" fill="none"/><path d="${d}" stroke="var(--led)" stroke-width="2.4" fill="none"/></g>` + tx(55 + i * 95, 140, n, 'vizlab')).join('')), q: mcq('Tu receptor de 137 MHz se satura con las emisoras de FM. ¿Qué filtro pones?', ['Rechazo de la banda de FM', 'Paso bajo a 50 MHz', 'Ninguno: más ganancia', 'Un filtro de audio'], 'Quita solo lo que molesta.') },
      { title: 'Filtrar antes de amplificar', text: 'Una señal fuerte fuera de tu banda (una antena de telefonía, las emisoras de FM) satura el primer amplificador aunque no la quieras oír. El filtro va <b>delante</b> del amplificador del receptor: detrás, el daño ya está hecho. En el emisor es al revés: el paso bajo va a la salida, antes de la antena.', q: mcq('Un receptor de 1090 MHz empeora cerca de una antena de telefonía. ¿Dónde va el filtro de 1090 MHz?', ['Antes del primer amplificador', 'Después del receptor', 'En el audio', 'No hace falta filtro'], 'Que no llegue al amplificador lo que no quieres.') }
    ] },
    rf_osc: { name: 'Osciladores y PLL', alts: [
      { title: 'Un amplificador que se escucha', text: 'Un oscilador es un amplificador cuya salida vuelve a su entrada a través de un filtro: oscila a la frecuencia que fija ese filtro (un LC o, mucho más estable, un cristal). Si un amplificador se realimenta sin querer (mala masa, cables cerca), también oscila.', svg: SVG.oscLoop, q: mcq('¿Qué fija la frecuencia de un oscilador Colpitts?', ['Su circuito LC', 'La tensión de alimentación', 'La ganancia del transistor', 'La temperatura'], 'El filtro decide dónde se cumple la condición de oscilación.') },
      { title: 'El PLL multiplica el cristal', text: 'Lazo de un PLL: <b>VCO → divisor ÷N → detector de fase</b> (compara con el cristal) <b>→ filtro de lazo → tensión de control del VCO</b>. Se ajusta hasta que <b>fsal = N · fref</b>: cambiando N se sintoniza con la estabilidad del cristal. Prueba a sacar 868 MHz.', tune: { viz: 'rf_pll', params: { fr: { label: 'Cristal de referencia', val: 25, list: [10, 25, 26, 32], unit: 'MHz', dec: 0 }, N: { label: 'Divisor N', val: 40, min: 10, max: 100, step: 0.01, dec: 2 }, ppm: fx(2.5) } }, q: mcq('Referencia de 25 MHz y N = 17,36. ¿Frecuencia de salida?', ['434 MHz', '42,36 MHz', '1,44 MHz', '868 MHz'], '25 × 17,36 = 434 MHz.') }
    ] },
    rf_ppm: { name: 'Error de frecuencia en ppm', alts: [
      { title: 'Partes por millón', text: '<b>Error (Hz) = f × ppm / 10⁶</b>. Un cristal de ±20 ppm en 868 MHz: 868·10⁶ × 20·10⁻⁶ ≈ 17,4 kHz. Cuanto más alta es la frecuencia, más hercios de error para los mismos ppm.', q: mcq('¿Cuánto se desvía un oscilador de ±10 ppm a 2,4 GHz?', ['24 kHz', '2,4 kHz', '240 kHz', '24 Hz'], '2,4·10⁹ × 10·10⁻⁶ = 24 000 Hz.') },
      { title: 'Cambia el cristal', text: 'Con la salida en 868 MHz, cambia la precisión del cristal. Un cristal normal (±20 ppm) se mueve más de 17 kHz; uno compensado en temperatura (TCXO, ±2,5 ppm), unos 2 kHz.', tune: { viz: 'rf_pll', params: { fr: fx(25), N: fx(34.72), ppm: { label: 'Precisión del cristal', val: 20, list: [0.5, 2.5, 10, 20, 50], unit: 'ppm', dec: 1 } } }, q: mcq('A 868 MHz, ¿cuánto se desvía un TCXO de ±2,5 ppm?', ['Unos 2,2 kHz', 'Unos 22 kHz', 'Unos 220 Hz', 'Unos 2,5 Hz'], '868·10⁶ × 2,5·10⁻⁶ ≈ 2170 Hz.') },
      { title: 'Error contra ancho de banda', text: 'Lo que importa es el error comparado con el canal. 17 kHz no molestan en un canal de 500 kHz, pero en un canal de 7,8 kHz el receptor ni siquiera encuentra la señal: por eso esos equipos llevan <b>TCXO</b> (±0,5–2,5 ppm).', q: mcq('¿Por qué un módulo con canales de 7,8 kHz lleva TCXO?', ['Un error de varios kHz se saldría del canal', 'Para transmitir más potencia', 'Para no necesitar antena', 'Para gastar menos'], 'El error debe ser pequeño frente al ancho de banda.') }
    ] },
    rf_mixer: { name: 'Mezclador y frecuencia intermedia', alts: [
      { title: 'Suma y diferencia', text: 'Un <b>mezclador</b> multiplica dos señales. Por trigonometría, el producto de dos senoides contiene su <b>suma</b> y su <b>diferencia</b>. Un superheterodino se queda con la diferencia: la <b>frecuencia intermedia (FI)</b>, siempre la misma, fácil de filtrar y amplificar.', svg: SVG.mixer, q: mcq('Mezclas 100 MHz con un oscilador local de 110,7 MHz. ¿Qué sale?', ['10,7 MHz y 210,7 MHz', 'Solo 110,7 MHz', '5,35 MHz', 'Solo 100 MHz'], 'Diferencia y suma.') },
      { title: 'Mete la emisora en la FI', text: 'Mueve el oscilador local hasta que la diferencia caiga dentro del filtro de 10,7 MHz. Verás que hay dos posiciones: OL por encima o por debajo de la emisora.', tune: { viz: 'rf_mix', params: { frf: { label: 'Emisora', val: 95, list: [88, 95, 100, 104], unit: 'MHz', dec: 0 }, flo: { label: 'Oscilador local', val: 100, min: 60, max: 130, step: 0.1, unit: 'MHz', dec: 1 } } }, q: mcq('Onda media con FI de 455 kHz y OL por encima. Para sintonizar 1000 kHz, ¿dónde va el OL?', ['1455 kHz', '545 kHz', '1000 kHz', '455 kHz'], '1000 + 455.') },
      { title: 'Una frecuencia fija para todo', text: 'El oscilador local se mueve con el dial para que siempre <b>|OL − RF| = FI</b>: con el OL por encima, <b>OL = RF + FI</b> (95 MHz + 10,7 = 105,7 MHz). Así los filtros y amplificadores finos trabajan siempre a la misma FI y se diseñan una sola vez.', q: mcq('FM con FI de 10,7 MHz y OL por encima. Sintonizas 95 MHz. ¿OL?', ['105,7 MHz', '84,3 MHz', '95 MHz', '10,7 MHz'], '95 + 10,7.') }
    ] },
    rf_image: { name: 'Frecuencia imagen', alts: [
      { title: 'La otra entrada a la FI', text: 'La diferencia no tiene signo: con el oscilador local por encima, <b>fRF + 2·FI</b> también da la misma FI. Esa es la <b>frecuencia imagen</b>. Hay que filtrarla <b>antes</b> del mezclador, con el filtro de RF; después ya es imposible separarla.', q: mcq('Sintonizas 98 MHz con FI = 10,7 MHz y el oscilador por encima. ¿Imagen?', ['119,4 MHz', '87,3 MHz', '108,7 MHz', '76,6 MHz'], '98 + 2 × 10,7 = 119,4 MHz.') },
      { title: 'Míralo en el dial', text: 'Con el OL por encima, la imagen está otra FI más allá del oscilador: <b>RF + 2·FI</b>. Con FI de 455 kHz, en FM la imagen cae dentro de la banda; con 10,7 MHz se va 21,4 MHz más arriba, fuera de los 20,5 MHz que mide la banda.', tune: { viz: 'rf_superhet', params: SH(96.3, 0.455, 1) }, q: mcq('FM con FI = 10,7 MHz y OL por encima. Sintonizas 90 MHz. ¿Imagen?', ['111,4 MHz', '100,7 MHz', '68,6 MHz', '79,3 MHz'], '90 + 21,4 = 111,4 MHz.') }
    ] },
    rf_overload: { name: 'Saturación e intermodulación', alts: [
      { title: 'Un techo para cada amplificador', text: 'El <b>P1dB</b> es la potencia a la que la ganancia ya ha caído 1 dB. A la entrada, el techo es el P1dB de salida menos la ganancia (20 dB de ganancia y +10 dBm → unos −10 dBm). Cerca de él, dos señales fuertes f₁ y f₂ generan <b>2f₁ − f₂ y 2f₂ − f₁</b>: fantasmas muy cerca de ellas.', q: mcq('Señales fuertes en 433 y 434 MHz. ¿Dónde caen los productos de intermodulación de tercer orden?', ['432 y 435 MHz', '1 y 867 MHz', '433,5 MHz', '866 y 868 MHz'], '2 × 433 − 434 = 432; 2 × 434 − 433 = 435.') },
      { title: 'Empuja el amplificador', text: 'Sube la potencia de entrada: al principio la salida crece dB a dB; cerca del techo, la curva se dobla (compresión). Mira a la derecha: los productos de intermodulación (rojo) crecen tres veces más deprisa que las señales.', tune: { viz: 'rf_amp', params: { pin: { label: 'Potencia de entrada', val: -30, min: -50, max: 5, step: 1, unit: 'dBm', dec: 0 } } }, q: mcq('Bajas 1 dB las dos señales de entrada. ¿Cuánto bajan los productos de intermodulación de tercer orden?', ['Unos 3 dB', '1 dB', 'Nada', '9 dB'], 'Crecen (y bajan) con el cubo: 3 dB por cada dB.') },
      { title: 'Ganancia justa, no máxima', text: 'Demasiada señal también falla: un LNA de 30 dB delante de un receptor en una ciudad, o dos módulos de radio a 14 dBm separados 20 cm, llevan el receptor por encima de su techo. Síntomas: paquetes perdidos, emisoras fantasma, todo peor. Remedio: menos ganancia, un filtro delante o más distancia.', q: mcq('Dos módulos a 0 dBm a 10 cm pierden paquetes; a 2 m van bien. ¿Por qué?', ['El receptor se satura con tanta señal', 'Falta potencia', 'Están en canales distintos', 'Por la polarización'], 'Todo receptor tiene un nivel máximo de entrada.') }
    ] },

    /* --- Líneas y antenas --- */
    rf_tline: { name: 'Líneas de transmisión', alts: [
      { title: 'Cuándo un cable es una línea', text: 'Si un cable o pista mide más de unos <b>λ/10</b>, la señal tarda en recorrerlo y viaja como una onda: es una línea de transmisión. Su <b>Z0</b> (50 Ω en radio, 75 Ω en TV) es la relación tensión/corriente de esa onda y la fijan la geometría y el aislante.', tune: { viz: 'rf_tlen', params: { f: { label: 'Frecuencia', val: 10, list: [1, 10, 100, 433.92, 868, 2440], unit: 'MHz', dec: 2 }, len: { label: 'Longitud', val: 10, list: [1, 2, 5, 10, 20, 50, 100, 300], unit: 'cm', dec: 0 } } }, q: mcq('A 2,4 GHz (λ ≈ 12,5 cm), ¿desde qué longitud tratas una pista como línea?', ['Desde 1,2 cm aproximadamente', 'Desde 12 cm', 'Desde 1,2 m', 'Nunca'], 'λ/10.') },
      { title: 'Geometría, no longitud', text: 'Z0 depende de la relación entre diámetros y del aislante: <b>Z0 = (138 / √εr)·log₁₀(D / d)</b>. Un cable de 50 Ω mide 50 Ω tenga 1 m o 100 m. Prueba a conseguir 50 y 75 Ω cambiando D/d.', tune: { viz: 'rf_coax', params: { dd: { label: 'Relación de diámetros D/d', val: 2, min: 1.5, max: 8, step: 0.1, dec: 1 }, er: { label: 'Aislante εr (1 aire · 1,5 espuma · 2,1 PTFE · 2,25 PE)', val: 2.25, list: [1, 1.5, 2.1, 2.25], dec: 2 } } }, q: mcq('Mides con el multímetro un coaxial de 50 Ω abierto en el otro extremo. ¿Qué marca?', ['Circuito abierto', '50 Ω', '0 Ω', '500 Ω'], 'Z0 no es una resistencia: en continua solo hay un aislante.') },
      { title: 'Más lenta dentro del cable', text: 'Dentro del cable la onda va más despacio: <b>VF = 1/√εr</b> (polietileno macizo 0,66; espumado 0,8–0,85). Una longitud eléctrica se corta físicamente más corta: λ/4 en el aire × VF. A 433,92 MHz: 17,3 cm × 0,66 ≈ 11,4 cm.', q: mcq('Un λ/4 a 145 MHz (51,7 cm en el aire) en coaxial con VF = 0,66. ¿Longitud física?', ['Unos 34 cm', 'Unos 78 cm', 'Unos 51,7 cm', 'Unos 13 cm'], '51,7 × 0,66 ≈ 34,1 cm.') }
    ] },
    rf_match: { name: 'Adaptar impedancias', alts: [
      { title: 'Anular y transformar', text: 'Adaptar es que la carga “parezca” 50 Ω puros. Primero se <b>anula la reactancia</b> (una inductiva con un condensador, una capacitiva con una bobina) y luego se <b>transforma la resistencia</b>: con una red en L o con un tramo de λ/4 de <b>Z0 = √(Z₁·Z₂)</b> (200 Ω a 50 Ω → 100 Ω).', q: mcq('¿Qué Z0 necesita un λ/4 para adaptar 12,5 Ω a 50 Ω?', ['25 Ω', '31,25 Ω', '62,5 Ω', '600 Ω'], '√(12,5 × 50) = 25 Ω.') },
      { title: 'El mapa de Smith', text: 'En la carta de Smith el <b>centro</b> es 50 Ω perfecto; la mitad <b>superior</b>, reactancia inductiva (positiva); la <b>inferior</b>, capacitiva. Adaptar es llevar el punto al centro. Muévelo tú.', tune: { viz: 'rf_smith', params: { R: { label: 'Resistencia', val: 25, min: 5, max: 300, step: 1, unit: 'Ω', dec: 0 }, X: { label: 'Reactancia', val: 50, min: -150, max: 150, step: 5, unit: 'Ω', dec: 0 } } }, q: mcq('Tu medida cae en la mitad inferior de la carta de Smith. ¿Qué tiene la antena?', ['Reactancia capacitiva', 'Reactancia inductiva', '50 Ω exactos', 'Un cortocircuito'], 'Abajo, capacitiva.') }
    ] },
    rf_line: { name: 'ROE, Γ y potencia reflejada', alts: [
      { title: 'El eco en el pasillo', text: 'Si la carga no tiene la misma impedancia que la línea (50 Ω), parte de la onda rebota. El <b>coeficiente de reflexión</b> lo mide: <b>Γ = (ZL − Z0) / (ZL + Z0)</b>. Se refleja |Γ|² de la potencia. La <b>ROE</b> resume lo mismo: <b>(1 + |Γ|) / (1 − |Γ|)</b>; y las pérdidas de retorno: <b>RL = −20·log|Γ|</b>.', svg: SVG.reflect, q: mcq('Una línea de 50 Ω termina en una carga de 50 Ω. ¿ROE?', ['1:1, no hay reflexión', '2:1', 'Infinita', '50:1'], 'Γ = 0 → ROE = 1.') },
      { title: 'Números de bolsillo', text: '· ROE 1,5 → |Γ| = 0,2 → se refleja el 4 %.\n· ROE 2 → |Γ| = 0,33 → el 11 %.\n· ROE 3 → |Γ| = 0,5 → el 25 % (llega el 75 %).\n· RL 20 dB → |Γ| = 0,1 → el 1 %.\nCon cargas resistivas, ROE = mayor / menor (100 Ω en 50 Ω → 2).', q: mcq('Una antena tiene ROE 2:1. ¿Qué parte de la potencia se refleja?', ['Alrededor del 11 %', 'La mitad', 'El 2 %', 'Toda'], '|Γ|² = (1/3)² ≈ 0,11.') },
      { title: 'Mira la onda estacionaria', text: 'Mueve la carga: con 50 Ω puros la tensión es plana a lo largo de la línea (ROE 1); al alejarte aparecen máximos y mínimos y la ROE sube.', tune: { viz: 'rf_swr', params: { R: { label: 'Resistencia de la carga', val: 150, min: 5, max: 300, step: 1, unit: 'Ω', dec: 0 }, X: { label: 'Reactancia (+ inductiva, − capacitiva)', val: 0, min: -150, max: 150, step: 5, unit: 'Ω', dec: 0 } } }, q: mcq('Una carga resistiva de 150 Ω en una línea de 50 Ω. ¿ROE?', ['3:1', '1,5:1', '2:1', '100:1'], 'Con cargas resistivas, ROE = mayor / menor = 150 / 50.') }
    ] },
    rf_connectors: { name: 'Conectores y cables de RF', alts: [
      { title: 'Cada conector, su sitio', text: '<b>SMA</b>: rosca, módulos y antenas pequeñas. <b>RP-SMA</b>: igual por fuera, con el pin cambiado de lado (si mezclas SMA y RP-SMA puede quedar sin pin central). <b>u.FL</b>: diminuto, en placa, aguanta solo unas decenas de conexiones. <b>BNC</b>: laboratorio. <b>N</b>: robusto y estanco. <b>F</b>: TV, 75 Ω.', svg: SVG.conn, q: mcq('¿Qué conector usarías en una antena exterior expuesta a la lluvia?', ['N, robusto y estanco', 'u.FL', 'RP-SMA de router', 'F de 75 Ω'], 'El N está pensado para exteriores y potencias mayores.') },
      { title: 'Pequeños puntos de fallo', text: 'Aprieta el SMA girando la tuerca, no el cable; no dobles el coaxial en curvas cerradas; sella los conectores exteriores con cinta autovulcanizante (el agua dentro cambia la impedancia y corroe); evita cadenas de adaptadores.', q: mcq('Una antena exterior va bien en seco y mal tras la lluvia. ¿Qué revisas primero?', ['El sellado del conector y del cable', 'La potencia del módulo', 'La modulación', 'La ionosfera'], 'Agua dentro del conector.') }
    ] },
    rf_feed: { name: 'Plano de tierra y balun', alts: [
      { title: 'La corriente tiene que volver', text: 'Un monopolo de λ/4 es medio dipolo: la otra mitad la pone un <b>plano de tierra</b> (chasis, placa o radiales). Sin él, el cable y la placa hacen de “otra mitad” y la antena funciona peor y de forma imprevisible.', svg: SVG.monopole, q: mcq('¿Qué le falta a un monopolo de 868 MHz soldado solo al conector, sin placa ni radiales?', ['Un plano de tierra', 'Un balun', 'Más potencia', 'Otro conector'], 'El monopolo necesita su “espejo”.') },
      { title: 'El síntoma de la mano', text: 'Un dipolo es simétrico: alimentado con coaxial sin <b>balun</b>, la corriente sube por el exterior de la malla y el cable radia. Si la ROE cambia al tocar o mover el coaxial, pasa eso. Se corta con un choque (ferritas o unas vueltas de coaxial) junto a la alimentación.', svg: SVG.balun, q: mcq('La ROE de tu dipolo cambia cuando tocas el cable. ¿Qué añades?', ['Un choque de modo común (balun) junto a la antena', 'Un cable más largo', 'Más potencia', 'Un conector N'], 'Corta la corriente por el exterior de la malla.') }
    ] },
    rf_antenna: { name: 'Ganancia, directividad y diagrama', alts: [
      { title: 'Ganancia no es amplificar', text: 'Una antena no fabrica energía: la <b>concentra</b> en unas direcciones a costa de otras. La ganancia se mide en dBi y vale <b>eficiencia × directividad</b>: con un 50 % de eficiencia, 3 dB menos que la directividad. Un dipolo tiene 2,15 dBi; una Yagi de tres elementos, unos 7 dBi.', q: mcq('Una Yagi de 10 dBi apuntando al revés. ¿Qué recibes?', ['Mucho menos que con un dipolo', 'Lo mismo: la ganancia es fija', 'El doble', 'Más, por el reflejo'], 'Lo que gana hacia delante lo pierde hacia otras direcciones.') },
      { title: 'Gira y compara', text: 'Elige una antena y gira la dirección. La línea discontinua es la isotrópica (0 dBi): donde el diagrama sale por fuera, ganas; donde queda dentro, pierdes. Fíjate en que cuanto más ganancia, más estrecho el haz.', tune: { viz: 'rf_pattern', params: { type: { label: 'Antena: 1 isotrópica · 2 dipolo · 3 Yagi 3 · 4 Yagi 6 · 5 parche', val: 3, list: [1, 2, 3, 4, 5], dec: 0 }, ang: { label: 'Dirección', val: 0, min: 0, max: 180, step: 5, unit: '°', dec: 0 } } }, q: mcq('Al pasar de una Yagi de 3 elementos a una de 6, el haz…', ['Se estrecha y gana dB hacia delante', 'Se ensancha', 'No cambia', 'Se vuelve omnidireccional'], 'Más ganancia exige concentrar más.') },
      { title: 'Dar forma al haz', text: 'Cada antena reparte la energía a su manera: el dipolo, un donut alrededor de su eje; la <b>Yagi</b>, con un reflector algo más largo detrás y directores algo más cortos delante, un haz; el parche, su hemisferio delantero.', svg: SVG.yagi, q: mcq('En una Yagi, ¿cómo son los directores respecto al elemento activo?', ['Algo más cortos, delante', 'Algo más largos, detrás', 'Iguales', 'Mucho más largos, delante'], 'El reflector es el más largo y va detrás.') }
    ] },
    rf_vna: { name: 'Medir con el NanoVNA', alts: [
      { title: 'Qué mide', text: 'El VNA mide lo que vuelve (<b>S11</b>, reflexión: ROE y carta de Smith) y lo que atraviesa (<b>S21</b>, transmisión: filtros, cables, amplificadores). Antes de medir se calibra con abierto, corto y carga en el plano donde irá la antena.', svg: SVG.vna, q: mcq('Quieres medir cuánto atenúa un filtro. ¿Qué parámetro miras?', ['S21', 'S11', 'La ROE', 'La carta de Smith'], 'S21 es lo que pasa de un puerto al otro.') },
      { title: 'Un orden que no falla', text: '1) Rango de frecuencias y puntos. 2) Calibración abierto–corto–carga al final del cable. 3) Guardar. 4) Antena en su posición final, lejos de metales. 5) Leer ROE (S11) y Smith. Rango nuevo, calibración nueva.', q: mcq('Has calibrado y luego amplías el rango de barrido. ¿Qué haces?', ['Calibrar otra vez', 'Medir sin más', 'Cambiar de cable', 'Apagar y encender'], 'La corrección se guarda punto a punto.') }
    ] },

    /* --- Modulación y receptores --- */
    rf_am: { name: 'AM: portadora y bandas laterales', alts: [
      { title: 'Una portadora que sube y baja', text: 'En AM la amplitud sigue al audio: la envolvente es una copia del mensaje. Al 100 % de modulación la envolvente toca cero en los valles; más allá se recorta y distorsiona.', tune: { viz: 'rf_mod', params: { type: { val: 1, fixed: true }, m: MODM(0.6) } }, q: mcq('¿Qué ocurre si modulas una AM por encima del 100 %?', ['La envolvente se recorta: distorsión y espectro más ancho', 'Suena más fuerte sin problemas', 'Se convierte en FM', 'Nada'], 'La sobremodulación distorsiona.') },
      { title: 'El espectro de una AM', text: 'Mira el espectro: una portadora en el centro y dos <b>bandas laterales</b> en fc ± fm. El ancho es <b>2·fm</b>. Sube la profundidad: las laterales crecen, pero incluso al 100 % la portadora se queda con dos tercios de la potencia.', tune: { viz: 'rf_amfm', params: { type: fx(1), fm: { label: 'Audio más agudo', val: 4.5, list: [1, 3, 4.5, 5, 10, 15], unit: 'kHz', dec: 1 }, m: { label: 'Profundidad', val: 0.5, min: 0, max: 1, step: 0.05, dec: 2 }, df: fx(5) } }, q: mcq('AM en 594 kHz con audio de hasta 4,5 kHz. ¿Qué ocupa?', ['De 589,5 a 598,5 kHz', 'De 594 a 598,5 kHz', 'De 585 a 603 kHz', 'Solo 594 kHz'], 'fc ± fm.') }
    ] },
    rf_fm: { name: 'FM: desviación, Carson y ruido', alts: [
      { title: 'Lo que cambia es la frecuencia', text: 'En FM la amplitud es constante y la frecuencia se desvía <b>Δf</b> al ritmo del audio. Como la información no va en la amplitud, el receptor la recorta (limitador) y con ella casi todo el ruido de chispas y motores. Ancho de banda según Carson: <b>2·(Δf + fm)</b>.', q: mcq('¿Por qué la FM es menos sensible a los chasquidos de un motor que la AM?', ['Ese ruido va sobre todo en la amplitud, y la FM la recorta', 'Porque emite más potencia', 'Porque es digital', 'Porque usa otra antena'], 'La información va en la frecuencia.') },
      { title: 'Rayas y más rayas', text: 'Una FM no tiene solo dos bandas laterales: tiene muchas rayas separadas fm. Casi toda la potencia queda dentro del ancho de Carson (zona verde). Sube la desviación y mira cómo se ensancha.', tune: { viz: 'rf_amfm', params: { type: fx(2), fm: { label: 'Audio más agudo', val: 5, list: [1, 3, 4.5, 5, 10, 15], unit: 'kHz', dec: 1 }, m: fx(0.5), df: { label: 'Desviación', val: 5, list: [2.5, 5, 25, 50, 75], unit: 'kHz', dec: 1 } } }, q: mcq('Desviación de 5 kHz y audio de hasta 3 kHz. ¿Ancho según Carson?', ['16 kHz', '8 kHz', '10 kHz', '30 kHz'], '2 × (5 + 3) = 16 kHz.') },
      { title: 'Números de Carson', text: 'Suma desviación y audio y multiplica por 2. FM comercial: Δf = 75 kHz y audio de 15 kHz → 2 × 90 = 180 kHz (los canales van cada 200 kHz). Walkie estrecho: 2,5 y 3 kHz → 11 kHz, cabe en 12,5 kHz.', q: mcq('FM comercial (Δf = 75 kHz, audio de 15 kHz). ¿Ancho según Carson?', ['180 kHz', '90 kHz', '150 kHz', '30 kHz'], '2 × (75 + 15).') }
    ] },
    rf_mod: { name: 'Tipos de modulación', alts: [
      { title: 'Subirse a la portadora', text: 'Una portadora pura no lleva información. Para transmitir se cambia una de sus tres propiedades al ritmo del mensaje:\n· <b>Amplitud</b>: AM, ASK, OOK.\n· <b>Frecuencia</b>: FM, FSK, GFSK.\n· <b>Fase</b>: PSK. (QAM cambia amplitud y fase a la vez.)', q: mcq('Un mando de garaje enciende y apaga la portadora para enviar unos y ceros. ¿Qué modulación es?', ['OOK (una ASK todo o nada)', 'FM', 'PSK', 'QAM'], 'On-Off Keying.') },
      { title: 'Pruébalas todas', text: 'Cambia el tipo y mira qué cambia en la señal transmitida: en ASK la altura, en FSK la separación de las ondas y en BPSK un salto brusco de la onda en cada cambio de bit.', tune: { viz: 'rf_mod', params: { type: MODT(3), m: MODM(1) } }, q: mcq('En la señal transmitida, la amplitud es constante y las ondas se juntan o se separan con cada bit. ¿Qué modulación es?', ['FSK', 'ASK', 'OOK', 'AM'], 'Cambia la frecuencia: FSK.') },
      { title: 'Ejemplos que ya conoces', text: '· <b>OOK</b>: mandos de 433 MHz.\n· <b>GFSK</b>: Bluetooth Low Energy y muchos transceptores de 2,4 GHz.\n· <b>BPSK</b>: señal civil del GPS (la fase salta 180°).\n· <b>QAM</b>: WiFi rápido (amplitud y fase a la vez).', q: mcq('¿Qué modulación usa el Bluetooth Low Energy?', ['GFSK', 'OOK', 'QAM', 'AM'], 'FSK con filtro gaussiano.') }
    ] },
    rf_symbols: { name: 'Bits por símbolo', alts: [
      { title: 'log₂ de los estados', text: 'Con M estados distintos, cada símbolo lleva <b>log₂(M)</b> bits: 2 estados → 1 bit; QPSK (4) → 2; 16-QAM → 4; 64-QAM → 6; 256-QAM → 8. Más bits por símbolo dan más velocidad en el mismo ancho de banda, pero hace falta más SNR.', q: mcq('¿Cuántos bits lleva cada símbolo en 16-QAM?', ['4', '16', '8', '2'], '2⁴ = 16.') },
      { title: 'Puntos más apretados', text: 'Cada estado es un punto en el plano (constelación). Sube M: los puntos se juntan y la nube de ruido los mezcla antes. Sube la SNR para separarlos otra vez.', tune: { viz: 'rf_const', params: { M: { label: 'Estados M', val: 4, list: [2, 4, 16, 64, 256], dec: 0 }, snr: { label: 'SNR', val: 12, min: 0, max: 40, step: 1, unit: 'dB', dec: 0 } } }, q: mcq('Te alejas del router y la señal empeora. ¿Qué hace el WiFi?', ['Pasa a una modulación con menos bits por símbolo', 'Pasa a 256-QAM', 'Sube los bits por símbolo', 'Nada'], 'Menos estados toleran menos SNR.') }
    ] },
    rf_manchester: { name: 'Codificación Manchester', alts: [
      { title: 'Una transición en cada bit', text: 'Cada bit se parte en dos mitades de nivel opuesto: hay una transición en mitad de cada bit, el receptor recupera el reloj y la señal nunca se queda quieta. Con el convenio 1 = alto→bajo y 0 = bajo→alto, “1 0” se envía alto, bajo, bajo, alto. Hay un convenio contrario: emisor y receptor deben usar el mismo.', q: mcq('Con 1 = alto→bajo y 0 = bajo→alto, ¿cómo se envía “0 0”?', ['Bajo, alto, bajo, alto', 'Alto, bajo, alto, bajo', 'Bajo, bajo, alto, alto', 'Alto, alto, bajo, bajo'], 'Cada 0 es una subida en mitad del bit.') },
      { title: 'Compara las dos señales', text: 'Cambia el byte. Arriba, NRZ: un nivel por bit, que puede quedarse quieto mucho rato (0x00, 0xFF). Abajo, Manchester: nunca está quieto más de un bit entero.', tune: { viz: 'rf_manch', params: { byte: { label: 'Byte', val: 165, min: 0, max: 255, step: 1, dec: 0 } } }, q: mcq('Medio bit de 250 µs. ¿Cuánto dura como máximo un nivel dentro de los datos?', ['500 µs', '250 µs', '750 µs', '1 ms'], 'Dos medios bits iguales seguidos, como máximo.') }
    ] },
    rf_lora: { name: 'LoRa: símbolo y tiempo en aire', alts: [
      { title: 'Silbidos que suben', text: 'LoRa envía <b>chirps</b>: barridos que recorren todo el ancho de banda. Cada símbolo transporta SF bits y dura <b>2^SF / BW</b>: subir el SF en 1 duplica la duración del símbolo; duplicar el BW la reduce a la mitad.', svg: SVG.chirps, q: mcq('Pasas de SF9 a SF10 con el mismo ancho de banda. El símbolo dura…', ['El doble', 'La mitad', 'Lo mismo', '10 veces más'], 'Tsímbolo = 2^SF / BW.') },
      { title: 'Cada SF, el doble de aire', text: 'Como el símbolo dura el doble con cada paso de SF, el paquete entero también: 20 bytes tardan unos 57 ms con SF7 a 125 kHz y más de 1 s con SF12. Subir el BW de 125 a 500 kHz lo acorta cuatro veces.', q: mcq('20 bytes tardan unos 57 ms con SF7 a 125 kHz. ¿Aproximadamente cuánto con SF9?', ['Unos 185 ms (algo más de ×3)', 'Unos 57 ms', 'Unos 114 ms', 'Unos 29 ms'], 'Cada paso de SF casi duplica el tiempo en aire.') },
      { title: 'Juega con el reloj', text: 'Mueve SF y BW: el símbolo dura 2^SF / BW (SF7 a 125 kHz: 1,024 ms; SF12: 32,8 ms). Mira cómo el tiempo en aire se dispara al subir el SF y cae al subir el BW.', tune: { viz: 'rf_lora', params: LORA }, q: mcq('SF8 con 250 kHz. ¿Duración de un símbolo?', ['1,024 ms', '2,048 ms', '0,512 ms', '32 ms'], '2⁸ / 250 kHz = 256 / 250 ≈ 1,024 ms.') }
    ] },
    rf_loracfg: { name: 'LoRa: parámetros que deben coincidir', alts: [
      { title: 'Hablar el mismo idioma', text: 'Para que dos nodos LoRa se entiendan deben coincidir <b>frecuencia, SF, ancho de banda, tasa de codificación, palabra de sincronismo</b>, preámbulo y CRC. Con SF o BW distintos, el receptor ni siquiera ve el paquete. Todo eso es la capa física, LoRa; <b>LoRaWAN</b> es un protocolo de red que va encima.', q: mcq('Un nodo usa SF10 y la puerta de enlace escucha solo SF9, con el mismo BW. ¿Qué pasa?', ['No recibe los paquetes', 'Los recibe más despacio', 'Los recibe mejor', 'Se suman'], 'El SF debe coincidir.') },
      { title: 'SF distintos casi no se ven', text: 'Los chirps de SF distintos tienen pendientes distintas: son casi <b>ortogonales</b>. Un receptor de SF7 ve un paquete de SF8 casi como ruido. Dos redes con SF distintos comparten canal sin destruirse, pero un nodo mal configurado no se comunica con nadie.', svg: SVG.chirps, q: mcq('Dos nodos transmiten a la vez en el mismo canal, uno con SF7 y otro con SF10. ¿Qué ocurre?', ['Se interfieren poco: SF distintos son casi ortogonales', 'Se destruyen siempre los dos', 'Sus potencias se suman en el receptor', 'Solo llega el de SF10'], 'Cada receptor solo “ve” su SF.') }
    ] },
    rf_rxtypes: { name: 'Tipos de receptor', alts: [
      { title: 'De la galena al superheterodino', text: '<b>Galena</b>: LC, diodo y auricular, sin pilas. <b>Superregenerativo</b>: oscila y se apaga miles de veces por segundo; baratísimo y sensible pero ruidoso y poco selectivo. <b>Superheterodino</b>: antena → RF → mezclador con OL → FI → demodulador → audio; selectivo y estable.', svg: SVG.superhet, q: mcq('¿Qué receptor elegirías para un enlace de 433 MHz fiable en una zona con muchas interferencias?', ['Un superheterodino', 'Un superregenerativo', 'Una galena', 'Cualquiera: son iguales'], 'Más selectivo y estable.') },
      { title: 'Por qué los baratos “oyen ruido”', text: 'Los receptores sencillos de 433 MHz llevan control automático de ganancia: sin señal, suben la ganancia al máximo y por la salida sale ruido aleatorio. Los superregenerativos, además, dejan pasar mucho espectro. Por eso las tramas llevan preámbulo y sincronismo, y el decodificador ignora el ruido.', q: mcq('Sin ningún mando cerca, la salida de tu receptor de 433 MHz cambia sin parar. ¿Qué pasa?', ['Es normal: el control de ganancia amplifica el ruido', 'El receptor está roto', 'Alguien transmite siempre', 'Falta una resistencia de pull-up'], 'Por eso las tramas llevan preámbulo y sincronismo.') }
    ] },
    rf_iq: { name: 'I/Q: el signo de la frecuencia', alts: [
      { title: 'I y Q', text: 'Con una sola señal muestreada no sabes si algo está 10 kHz por encima o por debajo de la sintonía: dan la misma salida. Con dos versiones desfasadas 90° (<b>I</b> y <b>Q</b>) sí: el sentido de giro de I + jQ dice si la frecuencia es positiva o negativa.', svg: SVG.iqmix, q: mcq('¿Para qué sirven las dos señales I y Q?', ['Para distinguir frecuencias por encima y por debajo de la sintonía', 'Para tener el doble de volumen', 'Para el estéreo', 'Para ahorrar muestras'], 'Una sola señal real confunde +f con −f.') },
      { title: 'Un tiovivo visto de lado', text: 'Si miras un tiovivo solo de lado (I), no sabes si gira a derechas o a izquierdas. Con una segunda vista desde delante (Q) sí lo sabes. Pruébalo: quita Q y cambia el signo de la frecuencia.', tune: { viz: 'rf_iq', params: { df: { label: 'Frecuencia respecto a la sintonía', val: 2, list: [-3, -2, -1, 1, 2, 3], unit: 'kHz', dec: 0 }, q: { label: 'Señales: 0 solo I · 1 I y Q', val: 1, list: [0, 1], dec: 0 } } }, q: mcq('Ves una señal 50 kHz por encima de la sintonía y una copia más débil 50 kHz por debajo. ¿Qué es la copia?', ['Una imagen por desequilibrio entre I y Q', 'Otra emisora', 'Un armónico', 'Ruido térmico'], 'Un I/Q imperfecto refleja las señales al lado opuesto.') }
    ] },
    rf_sdr: { name: 'Muestreo del SDR: ancho y alias', alts: [
      { title: 'Digitalizar un trozo de espectro', text: 'Un SDR traslada una porción del espectro a frecuencia cero y la muestrea en I/Q. Con muestras complejas, la <b>tasa de muestreo es el ancho que ves</b>: a 2,4 MS/s, unos 2,4 MHz alrededor de la sintonía. Lo que queda fuera debe quitarlo un filtro; si no, se pliega dentro como un <b>alias</b>.', q: mcq('Tu SDR muestrea a 2,4 MS/s en I/Q. ¿Cuánto espectro ves a la vez?', ['Unos 2,4 MHz', '2,4 GHz', '1,2 kHz', '24 MHz'], 'Con I/Q, el ancho visible ≈ la tasa de muestreo.') },
      { title: 'Abre y cierra la ventana', text: 'Cambia la tasa de muestreo y la sintonía: el rectángulo naranja es lo que ve el SDR. Quita el filtro antialias y aparecerán fantasmas: emisoras de fuera plegadas dentro.', tune: { viz: 'rf_sdrwin', params: { fc: { label: 'Sintonía', val: 98, min: 88, max: 108, step: 0.1, unit: 'MHz', dec: 1 }, fs: { label: 'Tasa de muestreo', val: 2.048, list: [0.25, 1.024, 2.048, 2.4], unit: 'MS/s', dec: 3 }, aa: { label: 'Filtro antialias: 1 sí · 0 no', val: 1, list: [1, 0], dec: 0 } } }, q: mcq('Un SDR muestrea a 1 MS/s en I/Q. ¿Cuánto espectro ves?', ['Unos 1 MHz', '0,5 MHz', '2 MHz', '1 kHz'], 'Con I/Q, ancho ≈ tasa de muestreo.') }
    ] },
    rf_sdrghost: { name: 'Señales fantasma en el SDR', alts: [
      { title: 'Lista de sospechosos', text: '· <b>Pico central</b>: residuo de continua de la conversión; desplaza un poco la sintonía.\n· <b>Imagen</b> espejo por desequilibrio I/Q.\n· <b>Espurios por saturación</b>: con demasiada ganancia aparecen emisoras donde no las hay.\n· Ruido del USB y del ordenador.', svg: sv(150, ln('M15 120H285', 'currentColor', 1) + ln('M150 120V40', 'var(--err)', 3) + tx(150, 34, 'pico central (continua)', 'vizsm', 'middle', 'fill:var(--err)') + ln('M210 120V60', 'var(--ice)', 3) + tx(210, 54, 'señal real', 'vizsm') + ln('M90 120V96', 'var(--muted)', 2, 'stroke-dasharray="3 2"') + tx(90, 90, 'imagen I/Q', 'vizsm') + tx(150, 140, 'Al resintonizar, solo la señal real se queda')), q: mcq('Un pico fijo aparece siempre en el centro de la pantalla. ¿Qué es?', ['El residuo de continua del SDR', 'Una emisora potente', 'Un satélite', 'Ruido térmico'], 'Está siempre en la frecuencia de sintonía.') },
      { title: 'Dos pruebas rápidas', text: '1) <b>Mueve la sintonía</b>: una señal real se queda en su frecuencia absoluta; un espurio interno (como el pico central) se mueve con la sintonía o va al revés.\n2) <b>Baja la ganancia</b>: si una señal desaparece o baja mucho más que el ruido, era un fantasma por saturación.', q: mcq('Bajas 10 dB la ganancia y una “emisora” desaparece mientras el ruido apenas baja. ¿Qué era?', ['Un producto espurio por saturación', 'Una emisora real lejana', 'El residuo de continua', 'Una imagen del GPS'], 'Las señales reales bajan igual que todo lo demás.') }
    ] },

    /* --- Módulos con microcontroladores --- */
    rf_nrf: { name: 'Opciones del nRF24L01+', alts: [
      { title: 'ACK, reintentos y velocidad', text: 'Con Enhanced ShockBurst el receptor contesta solo con un ACK; si no llega, el emisor reintenta. <b>setRetries(d, n)</b> espera (d + 1) × 250 µs entre intentos y hace hasta n (máximo 15). A 250 kbps hay más alcance; a 2 Mbps, más velocidad. testRPD() solo dice si hay más de unos −64 dBm en el canal.', svg: SVG.ack, q: mcq('¿Qué espera hay entre reintentos con setRetries(3, 10)?', ['1 ms', '750 µs', '3 ms', '10 ms'], '(3 + 1) × 250 µs = 1000 µs.') },
      { title: 'Lo que mide y lo que no', text: 'El nRF24L01+ no da un nivel en dBm: <b>testRPD()</b> es un detector de un bit (¿más de unos −64 dBm?). Para estimar el enlace, cuenta ACK perdidos y reintentos. Velocidad y alcance están reñidos: 250 kbps llega más lejos; 2 Mbps ocupa 2 MHz.', q: mcq('Quieres saber si un canal está ocupado por una señal fuerte. ¿Qué usas?', ['testRPD(): indica si se superan unos −64 dBm', 'setRetries()', 'setDataRate()', 'openReadingPipe()'], 'Es un detector de un solo bit.') }
    ] },
    rf_24ghz: { name: 'La banda de 2,4 GHz', alts: [
      { title: 'Un mapa de la banda', text: 'La banda ISM va de <b>2400 a 2483,5 MHz</b>. El WiFi usa canales de 20 MHz centrados en 2412 (1), 2437 (6) y 2462 MHz (11); los anuncios de BLE están en 2402, 2426 y 2480 MHz, en los huecos; el nRF24 transmite en <b>2400 + canal</b> MHz; y el microondas radia en torno a 2450 MHz.', q: mcq('Un nRF24 en el canal 100. ¿Puedes transmitir en Europa?', ['No: 2500 MHz está fuera de la banda ISM', 'Sí, cualquier canal vale', 'Sí, a baja potencia', 'Solo de noche'], '2400 + 100 = 2500 MHz > 2483,5 MHz.') },
      { title: 'Busca un hueco', text: 'Mueve el canal del nRF24 sobre el mapa: verás cuándo cae encima de un canal WiFi, cuándo en un hueco y cuándo se sale de la banda.', tune: { viz: 'rf_band24', params: { ch: { label: 'Canal del nRF24', val: 10, min: 0, max: 125, step: 1, dec: 0 } } }, q: mcq('¿En qué frecuencia transmite un nRF24 en el canal 2?', ['2402 MHz', '2404 MHz', '2412 MHz', '2420 MHz'], '2400 + 2 = 2402 MHz, la misma que el primer anuncio de BLE.') }
    ] },
    rf_supply: { name: 'Picos de corriente al transmitir', alts: [
      { title: 'El tirón del emisor', text: 'Al transmitir, un módulo de radio pide picos de decenas o cientos de mA. Un regulador pequeño, cables finos o una batería baja no los dan: la tensión se hunde y el módulo falla o la placa se reinicia. Remedio: un condensador de 10–100 µF pegado al módulo y una fuente con margen.', q: mcq('Tu nodo de radio se reinicia siempre justo al transmitir. ¿Primera sospecha?', ['La alimentación se hunde con el pico de corriente', 'La frecuencia', 'La polarización de la antena', 'La palabra de sincronismo'], 'El síntoma coincide con el pico.') },
      { title: 'Míralo en el osciloscopio', text: 'Cambia el condensador, la resistencia de la fuente y la duración de la transmisión. El condensador tapa los picos cortos; en una transmisión larga, la fuente y los cables tienen que dar la corriente.', tune: { viz: 'rf_droop', params: { I: fx(120), t: { label: 'Duración del pico', val: 0.13, list: [0.13, 1, 5, 50, 300], unit: 'ms', dec: 2 }, R: { label: 'Resistencia de la fuente y los cables', val: 4, list: [0.2, 0.5, 1, 2, 4], unit: 'Ω', dec: 1 }, C: { label: 'Condensador junto al módulo', val: 0, list: [0, 10, 47, 100, 470, 1000], unit: 'µF', dec: 0 } } }, q: mcq('¿Qué mides para confirmar que el problema es la alimentación?', ['La tensión en los pines del módulo mientras transmite, con osciloscopio', 'La ROE de la antena', 'La frecuencia', 'La temperatura'], 'Las caídas duran milisegundos: un multímetro no las ve.') }
    ] },
    rf_debug: { name: 'Método para depurar una radio', alts: [
      { title: 'De abajo arriba', text: 'Orden: <b>alimentación</b> (tensión y picos al transmitir) → <b>comunicación con el chip</b> (leer un registro conocido: RegVersion, en 0x42 del SX1276, devuelve 0x12) → configuración idéntica en los dos extremos → frecuencia real → antena y ROE → enlace cerca y luego lejos.', svg: SVG.debug, q: mcq('El SX1276 no responde. ¿Qué compruebas antes de tocar el SF?', ['Que lea bien un registro conocido por SPI', 'El diagrama de la antena', 'El horizonte radio', 'La zona de Fresnel'], 'Si el bus no funciona, lo demás no importa.') },
      { title: 'Un cambio cada vez', text: 'Si cambias tres cosas a la vez y mejora, no sabes cuál fue: cambia una, mide y apunta. Y ten módulos de referencia: cambiar una pieza sospechosa por una buena es la prueba más rápida.', q: mcq('Cambias la antena y el enlace mejora 6 dB. ¿Qué haces ahora?', ['Apuntarlo y probar el siguiente cambio por separado', 'Cambiar a la vez el SF y la fuente', 'Deshacerlo', 'Nada más'], 'Un cambio cada vez, y con registro.') }
    ] },
    rf_rfsec: { name: 'Seguridad y privacidad de la radio', alts: [
      { title: 'Lo que se graba se repite', text: 'Un mando de <b>código fijo</b> envía siempre la misma trama: quien la grabe puede repetirla. La seguridad necesita un secreto que no viaje: códigos variables con contador y clave, o tarjetas con criptografía moderna.', svg: SVG.replay, q: mcq('¿Qué protege contra el ataque de repetición en un mando?', ['Un código variable con contador y clave secreta', 'Más potencia', 'Usar 868 MHz en vez de 433', 'Codificar en Manchester'], 'Cada trama solo vale una vez.') },
      { title: 'Lo que se emite en claro', text: 'Todo lo que se emite sin cifrar lo puede recibir cualquiera. Por eso un número fijo no debe abrir una puerta (se copia o se repite) ni delatar a una persona: los móviles cambian su dirección Bluetooth cada pocos minutos para que no se les pueda seguir.', q: mcq('¿Por qué un control de acceso no debe abrir solo comprobando un número fijo que emite la tarjeta?', ['Ese número se lee y se puede copiar', 'Ese número cambia cada día', 'Ese número está cifrado', 'Porque el lector es lento'], 'Identifica, pero no autentica.') }
    ] },
    rf_nfc: { name: 'Acoplamiento inductivo (RFID y NFC)', alts: [
      { title: 'Un transformador con aire en medio', text: 'Lector y tarjeta son dos bobinas acopladas, como el primario y el secundario de un transformador. El campo alterno del lector <b>alimenta</b> la tarjeta, y esta contesta cambiando la carga de su bobina. Es <b>campo cercano</b>, que cae muchísimo con la distancia: solo funciona a pocos centímetros.', svg: SVG.nfc, q: mcq('¿De dónde saca la energía una tarjeta RFID pasiva?', ['Del campo magnético del lector', 'De una pila interna', 'De la luz ambiente', 'Del calor de la mano'], 'No lleva batería: se alimenta del campo.') },
      { title: 'Aléjate y mira', text: 'Mueve la etiqueta: el campo cercano cae con el cubo de la distancia (18 dB cada vez que la duplicas, lejos de la bobina). A pocos centímetros la etiqueta deja de despertar.', tune: { viz: 'rf_nfc', params: { d: { label: 'Distancia', val: 8, min: 0.5, max: 20, step: 0.5, unit: 'cm', dec: 1 } } }, q: mcq('Un lector NFC funciona a 3 cm pero no a 20 cm. Sobre todo porque…', ['El campo cercano cae muchísimo con la distancia', 'La ley lo prohíbe', 'La tarjeta no tiene antena', 'Por la velocidad de la luz'], 'El acoplamiento inductivo solo funciona muy cerca.') },
      { title: 'Todo es sintonía', text: 'La bobina de la etiqueta y un condensador interno resuenan a la frecuencia del lector (13,56 MHz en NFC). Un metal cerca cambia la inductancia, desintoniza la etiqueta y absorbe el campo; las etiquetas para metal llevan una lámina de ferrita.', q: mcq('Una pegatina NFC sobre una lata de refresco no se lee. ¿Solución?', ['Una etiqueta con lámina de ferrita para superficies metálicas', 'Acercar un imán', 'Subir el volumen del móvil', 'Ponerla al sol'], 'La ferrita aparta el campo del metal.') }
    ] },
    rf_gnss: { name: 'Cómo calcula la posición el GNSS', alts: [
      { title: 'Medir tiempos', text: 'Cada satélite dice qué hora es y dónde está. El receptor mide cuánto tarda cada señal y calcula distancias. Su reloj es malo, así que el error de reloj es una incógnita más: <b>4 satélites</b> para x, y, z y tiempo.', svg: SVG.trilat, q: mcq('¿Por qué hacen falta 4 satélites para una posición 3D?', ['Hay 4 incógnitas: tres coordenadas y el error del reloj del receptor', 'Uno por cada punto cardinal', 'Por pura redundancia', 'Con 3 basta siempre'], 'El reloj del receptor no es atómico.') },
      { title: 'Geometría y precisión', text: 'Cada distancia tiene su error. Si dos satélites se ven casi en la misma dirección, sus franjas se cruzan en ángulo muy cerrado y el error de posición se multiplica: la <b>HDOP</b> sube. Abre el ángulo y mira cómo baja el factor.', tune: { viz: 'rf_dop2', params: { ang: { label: 'Ángulo entre los dos satélites', val: 20, min: 10, max: 90, step: 5, unit: '°', dec: 0 }, err: { label: 'Error de cada distancia', val: 3, list: [1, 3, 10], unit: 'm', dec: 0 } } }, q: mcq('Entre rascacielos solo ves satélites en una franja estrecha del cielo. ¿Qué pasa con la HDOP?', ['Sube: peor precisión', 'Baja: mejor precisión', 'No cambia', 'Se hace cero'], 'Mala geometría, más error.') }
    ] },
    rf_nmea: { name: 'Leer tramas NMEA', alts: [
      { title: 'Campos separados por comas', text: 'Una trama NMEA empieza por $, lleva emisor y tipo (GPGGA, GNRMC…) y campos separados por comas. En <b>GGA</b>: hora, latitud, N/S, longitud, E/W, calidad, <b>número de satélites</b>, HDOP, altitud… Cuenta las comas con calma.', svg: SVG.nmea, q: mcq('En esta trama GGA, ¿cuántos satélites se usan?', ['11', '1', '0,8', '12'], 'Tras la calidad (1) va el número de satélites.', { code: '$GPGGA,120000.00,4123.4567,N,00210.1234,E,1,11,0.8,…' }) },
      { title: 'Grados y minutos', text: 'La latitud llega como <b>ggmm.mmmm</b> y la longitud como gggmm.mmmm: grados enteros y minutos con decimales. Para grados decimales: <b>grados + minutos / 60</b>. “4123.4567,N” = 41 + 23,4567 / 60 = 41,3909°. S y W se escriben en negativo.', q: mcq('Esta longitud, en grados decimales, es…', ['−3,7030°', '3,4218°', '−34,2182°', '3,7030°'], '3 + 42,182 / 60 = 3,7030; W es negativo.', { code: '00342.1820,W' }) }
    ] },

    /* --- Escuchar y depurar --- */
    rf_listen: { name: 'Qué escuchar y con qué', alts: [
      { title: 'Por frecuencia', text: '· 87,5–108 MHz: radio FM (piloto estéreo de 19 kHz y RDS en 57 kHz).\n· 137 MHz: satélites meteorológicos.\n· 144,800 MHz: APRS. · 433,92 MHz: sensores y mandos.\n· 1090 MHz: ADS-B de aviones.\nComprueba siempre que un servicio sigue activo antes de planificar.', svg: sv(140, (() => { const X = f => 15 + (lg(f) - 1.9) / 1.2 * 270; return ln('M15 80H285', 'currentColor', 1) + [[98, 'FM', 50], [137, '137 sat.', 30], [144.8, 'APRS', 60], [433.92, '433,92', 40], [1090, 'ADS-B', 50]].map(([f, l, y]) => ln(`M${X(f).toFixed(1)} 80V${y + 6}`, 'var(--led)', 2.5) + tx(X(f).toFixed(1), y, l)).join('') + tx(15, 100, '80 MHz', 'vizsm', 'start') + tx(285, 100, '1,3 GHz', 'vizsm', 'end') + tx(150, 128, 'Escala logarítmica', 'vizsm'); })()), q: mcq('¿Qué se oye en 1090 MHz?', ['ADS-B de aviones', 'Radio FM', 'APRS', 'Satélites meteorológicos'], 'Los aviones emiten ahí su posición.') },
      { title: 'Por programa', text: '<b>SDR++, SDR# o GQRX</b>: explorar el espectro y escuchar FM o aficionados. <b>rtl_433</b>: sensores de 433 y 868 MHz. <b>dump1090</b>: aviones en 1090 MHz. <b>SatDump</b>: satélites meteorológicos. Antes de seguir un tutorial antiguo, comprueba que el servicio sigue emitiendo.', q: mcq('¿Qué programa decodifica una estación meteorológica de 433,92 MHz?', ['rtl_433', 'dump1090', 'SatDump', 'GQRX'], 'rtl_433 conoce cientos de sensores.') }
    ] },
    rf_doppler: { name: 'Desplazamiento Doppler', alts: [
      { title: 'La fórmula', text: '<b>Δf = f · v / c</b>, con v la velocidad a lo largo de la línea de visión. Un satélite a 7 km/s en 137 MHz: 137·10⁶ × 7000 / 3·10⁸ ≈ 3,2 kHz. Al acercarse la frecuencia sube; al alejarse, baja.', q: mcq('Un satélite se acerca a 7 km/s y emite en 435 MHz. ¿Desplazamiento?', ['Unos 10 kHz', 'Unos 1 kHz', 'Unos 100 kHz', 'Unos 3,2 kHz'], '435·10⁶ × 7000 / 3·10⁸ ≈ 10,2 kHz.') },
      { title: 'Sigue el pase', text: 'Mueve el tiempo a lo largo del pase: al principio el satélite se acerca (Δf positivo), justo encima no se acerca ni se aleja (Δf = 0) y al final se aleja (Δf negativo). Cambia la frecuencia: el desplazamiento crece en proporción.', tune: { viz: 'rf_dopp', params: { tm: { label: 'Minutos respecto al punto más cercano', val: -6, min: -7, max: 7, step: 0.5, unit: 'min', dec: 1 }, f: { label: 'Frecuencia del satélite', val: 137.1, list: [137.1, 145.8, 435], unit: 'MHz', dec: 1 } } }, q: mcq('Durante un pase, ¿cómo cambia la frecuencia recibida?', ['Empieza alta, pasa por la nominal y acaba baja', 'Empieza baja y acaba alta', 'No cambia', 'Sube todo el rato'], 'Se acerca y luego se aleja.') }
    ] },
    rf_rfi: { name: 'Interferencias domésticas', alts: [
      { title: 'Fuentes y caminos', text: 'Fuentes conmutadas baratas, bombillas LED, adaptadores PLC, inversores y motores conmutan con flancos bruscos y generan ruido de banda ancha, sobre todo en onda media y HF. Sale por los cables (<b>conducido</b>) y los cables lo radian. Casi siempre va en <b>modo común</b>: una ferrita alrededor del cable entero lo frena sin tocar la corriente útil.', svg: SVG.cmode, q: mcq('¿Dónde pones una ferrita de clip para frenar el ruido de un cargador?', ['Alrededor del cable entero, cerca del cargador', 'Solo en uno de los hilos', 'En la antena de la radio', 'Dentro del enchufe'], 'El modo común va igual por todos los hilos.') },
      { title: 'Caza con método', text: 'Mide primero el suelo de ruido de referencia; recorre la casa con una radio de onda media de pilas entre emisoras (el ruido sube mucho cerca de la fuente culpable); desenchufa los sospechosos de uno en uno; aplica remedios (ferritas, sustituir el aparato); y vuelve a medir con la misma ganancia.', q: mcq('¿Por qué conviene medir el suelo de ruido antes de tocar nada?', ['Sin referencia no sabrás si has mejorado', 'Porque la radio se calienta', 'Para cumplir la ley', 'No hace falta'], 'Medir antes y después.') }
    ] }
  });


  /* ===================== GENERADORES =====================
     Cada ejercicio generado lleva su pista (h): orienta sin dar la respuesta. */
  {
    const { pick, ri, fmt, MC, N } = Gen.helpers;
    const L10 = Math.log10;
    const fP = mw => fW(mw / 1000);
    const C = 299.792458; // m·MHz
    const Nh = (q, a, u, e, tol, h) => ({ ...N(q, a, u, e, tol), h });
    const mn = x => String(x).replace('-', '−');

    Gen.add('rf_speed', () => {
      const [d, what] = pick([[300, 'una emisora a 300 km'], [3000, 'un enlace de 3000 km'], [36000, 'un satélite geoestacionario (unos 36 000 km)'], [20200, 'un satélite GPS (unos 20 200 km)'], [384400, 'la Luna (unos 384 400 km)'], [600, 'un avión a 600 km']]);
      const ms = d / 299792.458 * 1000;
      return Nh(`¿Cuántos milisegundos tarda la señal de ${what} en llegarte?`, ms, 'ms', `t = d / c = ${fmt(d)} km / 300 000 km/s ≈ ${fmt(ms, 2)} ms.`, Math.max(0.02, ms * 0.02), 'Divide los km entre 300 000 km/s y pasa los segundos a ms (× 1000).');
    }, 'rf_speed');

    Gen.add('rf_lambda', () => {
      const f = pick([7, 14, 27, 50, 88, 100, 137, 145, 433.92, 868, 1090, 1575.42, 2440]);
      const lam = C / f, h = 'λ (m) = 300 / f (MHz). Mira la unidad que te piden.';
      if (lam >= 1) return Nh(`¿Qué longitud de onda tiene una señal de ${fmt(f)} MHz? (en metros)`, lam, 'm', `λ = c / f ≈ 300 / ${fmt(f)} = ${fmt(lam, 2)} m.`, Math.max(0.02, lam * 0.02), h);
      return Nh(`¿Qué longitud de onda tiene una señal de ${fmt(f)} MHz? (en centímetros)`, lam * 100, 'cm', `λ = 300 / ${fmt(f)} = ${fmt(lam, 4)} m = ${fmt(lam * 100, 1)} cm.`, Math.max(0.3, lam * 100 * 0.02), h);
    }, 'rf_wave');

    Gen.add('rf_band', () => {
      const [f, txt] = pick([[0.125, '125 kHz (llaveros RFID)'], [0.198, '198 kHz (onda larga)'], [1.008, '1008 kHz (onda media)'], [7.1, '7,1 MHz (onda corta)'], [13.56, '13,56 MHz (NFC)'], [27, '27 MHz'], [98, '98 MHz (FM)'], [145, '145 MHz'], [433.92, '433,92 MHz'], [1575.42, '1575,42 MHz (GPS)'], [2440, '2,44 GHz (WiFi)'], [5800, '5,8 GHz']]);
      const b = bandName(f), all = ['LF', 'MF', 'HF', 'VHF', 'UHF', 'SHF'], i = all.indexOf(b);
      return MC(`¿En qué banda cae ${txt}?`, b, [all[i + 1] || all[i - 2], all[i - 1] || all[i + 2], all[(i + 3) % 6]], `Pasa a MHz y busca entre qué límites (todos empiezan por 3) cae: ${b}.`, { h: 'Los límites son 0,3 · 3 · 30 · 300 · 3000 MHz.' });
    }, 'rf_bands');

    Gen.add('rf_antLen', () => {
      const f = pick([137, 145, 433.92, 868, 1090, 2440]);
      const lam = C / f * 100, dip = pick([true, false]);
      const cm = x => fmt(x, 1) + ' cm';
      if (dip) return MC(`Cortas un dipolo de media onda para ${fmt(f)} MHz con un factor de acortamiento de 0,95. ¿Longitud total aproximada?`, cm(lam / 2 * 0.95), [cm(lam / 4 * 0.95), cm(lam * 0.95), cm(lam / 2 / 0.95 * 2), cm(lam / 20 * 0.95)], `λ = ${cm(lam)}; λ/2 = ${cm(lam / 2)}; × 0,95 = ${cm(lam / 2 * 0.95)}. Córtalo algo más largo y ajústalo midiendo.`, { h: 'Calcula λ, quédate con la mitad y multiplica por 0,95.' });
      return MC(`¿Cuánto mide, en teoría, un monopolo de cuarto de onda para ${fmt(f)} MHz?`, cm(lam / 4), [cm(lam / 2), cm(lam), cm(lam / 40), cm(lam / 8)], `λ = 300 / ${fmt(f)} = ${cm(lam)}; λ/4 = ${cm(lam / 4)}. En la práctica, un 3–5 % más corto.`, { h: 'Atajo: λ/4 en cm ≈ 7500 / f en MHz.' });
    }, 'rf_antsize');

    Gen.add('rf_trimGen', () => {
      const [L0, ft, kind] = pick([[8.8, 868, 'monopolo'], [9.2, 868, 'monopolo'], [17.6, 433.92, 'monopolo'], [16.8, 433.92, 'monopolo'], [34, 433.92, 'dipolo'], [52, 145, 'monopolo']]);
      const fm = Math.round(ft * pick([0.93, 0.95, 0.97, 1.03]) * 10) / 10, Ln = L0 * fm / ft;
      return Nh(`Un ${kind} de ${fmt(L0)} cm resuena en ${fmt(fm)} MHz y lo quieres en ${fmt(ft)} MHz. ¿Qué longitud tendrá que tener? (en cm)`, Ln, 'cm', `L nueva = ${fmt(L0)} × ${fmt(fm)} / ${fmt(ft)} ≈ ${fmt(Ln, 2)} cm. ${Ln < L0 ? 'Hay que recortar.' : 'Habría que alargar: mejor cortar otro un poco más largo.'}`, Math.max(0.05, Ln * 0.01), 'La longitud va al revés que la frecuencia: L × f medida / f deseada.');
    }, 'rf_trim');

    Gen.add('rf_horizon', () => {
      const h1 = pick([2, 4, 9, 16, 25, 36, 100]), h2 = pick([1, 4, 9, 25, 100, 400, 10000]);
      const d = 4.12 * (Math.sqrt(h1) + Math.sqrt(h2));
      return Nh(`Una antena a ${h1} m y otra a ${fmt(h2)} m de altura. ¿Horizonte radio aproximado en km?`, d, 'km', `d ≈ 4,12 · (√${h1} + √${h2}) = 4,12 · (${fmt(Math.sqrt(h1), 2)} + ${fmt(Math.sqrt(h2), 2)}) = ${fmt(d, 1)} km.`, Math.max(0.5, d * 0.03), 'Saca la raíz de cada altura (en metros), súmalas y multiplica por 4,12.');
    }, 'rf_horizon');

    Gen.add('rf_dbm2mw', () => {
      const d = pick([-30, -20, -13, -10, -3, 0, 3, 6, 10, 13, 14, 17, 20, 23, 27, 30, 33, 40]);
      const mw = Math.pow(10, d / 10);
      return MC(`¿Qué potencia son ${mn(d)} dBm?`, fP(mw), [fP(mw * 10), fP(mw / 10), fP(Math.pow(10, d / 20)), fP(mw * 2), fP(mw / 2)], `P = 1 mW × 10^(${mn(d)}/10) = ${fP(mw)}. Recuerda: +10 dB es ×10 y +3 dB es ×2.`, { h: 'Parte de 0 dBm = 1 mW y avanza a saltos de 10 dB (×10) y 3 dB (×2).' });
    }, 'rf_db');

    Gen.add('rf_mw2dbm', () => {
      const mw = pick([0.001, 0.01, 0.1, 0.5, 1, 2, 5, 10, 25, 50, 100, 200, 500, 1000, 2000]);
      const d = 10 * L10(mw);
      return Nh(`Convierte ${fP(mw)} a dBm.`, d, 'dBm', `dBm = 10 · log₁₀(${fmt(mw, 3)} mW / 1 mW) = ${fmt(d, 1)} dBm.`, 0.3, 'Pásalo a mW, haz 10·log₁₀ y no olvides el signo si es menos de 1 mW.');
    }, 'rf_db');

    Gen.add('rf_dbratio', () => {
      const r = pick([2, 4, 8, 10, 20, 100, 1000, 0.5, 0.25, 0.1, 0.01]);
      const d = 10 * L10(r);
      const s = x => (x > 0 ? '+' : '') + mn(fmt(x, 0)) + ' dB';
      return MC(`Una potencia se multiplica por ${fmt(r)}. ¿Cuántos dB son?`, s(d), [s(20 * L10(r)), s(d / 2), s(d + 3), s(-d)], `10 · log₁₀(${fmt(r)}) ≈ ${s(d)}. En potencia se usa 10·log; 20·log es para tensiones.`, { h: 'Descompón el factor en ×2 (3 dB) y ×10 (10 dB). Si es menor que 1, los dB son negativos.' });
    }, 'rf_dbratio');

    Gen.add('rf_chain', () => {
      const pt = pick([0, 10, 13, 14, 17, 20]), lc = pick([0.5, 1, 1.5, 2, 3]), con = pick([0.2, 0.4]), g = pick([0, 2.15, 3, 5, 7]);
      const e = pt - lc - con + g;
      return Nh(`Un emisor de ${pt} dBm, ${fmt(lc)} dB de pérdida en el cable, ${fmt(con)} dB en conectores y una antena de ${fmt(g)} dBi. ¿PIRE en dBm?`, e, 'dBm', `${pt} − ${fmt(lc)} − ${fmt(con)} + ${fmt(g)} = ${fmt(e, 2)} dBm. En dB todo se suma o se resta.`, 0.1, 'Empieza en los dBm del emisor: resta cada pérdida y suma la ganancia de la antena.');
    }, 'rf_chain');

    Gen.add('rf_erp', () => {
      const [mw, sub] = pick([[10, '433,05–434,79 MHz'], [25, '868,0–868,6 MHz'], [500, '869,4–869,65 MHz'], [25, '868,7–869,2 MHz']]);
      const erp = 10 * L10(mw), eirp = erp + 2.15;
      return Nh(`La sub-banda ${sub} permite ${mw} mW PRA (referida a un dipolo). ¿Cuánto es en dBm PIRE (referida a la isotrópica)?`, eirp, 'dBm', `${mw} mW = ${fmt(erp, 1)} dBm PRA; PIRE = PRA + 2,15 dB = ${fmt(eirp, 2)} dBm.`, 0.15, 'Pasa los mW a dBm y suma los 2,15 dB que el dipolo tiene sobre la isotrópica.');
    }, 'rf_eirp');

    Gen.add('rf_fspl', () => {
      const d = pick([0.1, 0.5, 1, 2, 5, 10, 20, 50]), f = pick([433.92, 868, 2440]);
      const L = 20 * L10(d) + 20 * L10(f) + 32.44;
      return Nh(`Pérdidas en espacio libre a ${fmt(d)} km y ${fmt(f)} MHz (en dB).`, L, 'dB', `FSPL = 20·log(${fmt(d)}) + 20·log(${fmt(f)}) + 32,44 = ${fmt(L, 1)} dB.`, 1, 'd en km y f en MHz: 20·log(d) + 20·log(f) + 32,44. Ojo: log de algo menor que 1 es negativo.');
    }, 'rf_fspl');

    Gen.add('rf_distx', () => {
      const k = pick([2, 4, 10, 0.5]);
      const d = 20 * L10(k);
      const s = x => fmt(Math.abs(x), 0) + ' dB';
      return MC(k > 1 ? `En espacio libre multiplicas la distancia por ${k}. ¿Cuánto aumentan las pérdidas?` : 'En espacio libre reduces la distancia a la mitad. ¿Cuánto disminuyen las pérdidas?', s(d), [s(d / 2), s(d * 2), s(k * 3)], 'Las pérdidas crecen con 20·log(d): ×2 en distancia = 6 dB; ×10 = 20 dB.', { h: 'Piensa en la esfera: doble de distancia, cuatro veces más superficie.' });
    }, 'rf_pathlaw');

    Gen.add('rf_noise', () => {
      const [bw, txt] = pick([[12500, '12,5 kHz'], [125000, '125 kHz'], [250000, '250 kHz'], [500000, '500 kHz'], [1e6, '1 MHz'], [2e6, '2 MHz'], [20e6, '20 MHz']]), nf = pick([3, 5, 6, 8, 10]);
      const n = -174 + 10 * L10(bw) + nf;
      return Nh(`Un receptor de ${txt} de ancho de banda con figura de ruido de ${nf} dB. ¿Suelo de ruido en dBm?`, n, 'dBm', `−174 + 10·log(${bw}) + ${nf} = ${fmt(n, 1)} dBm.`, 0.6, 'Pasa el ancho de banda a Hz: −174 + 10·log(BW) + NF.');
    }, 'rf_noise');

    Gen.add('rf_sens', () => {
      const [bw, txt, snr, what] = pick([[12500, '12,5 kHz', 10, 'un enlace FSK lento'], [125000, '125 kHz', -10, 'una modulación de espectro ensanchado'], [250000, '250 kHz', 8, 'un enlace FSK'], [1e6, '1 MHz', 12, 'un enlace de datos rápido'], [2e6, '2 MHz', 10, 'un enlace GFSK de 2 Mbps'], [125000, '125 kHz', -15, 'una modulación de espectro ensanchado']]), nf = pick([4, 6, 8]);
      const s = -174 + 10 * L10(bw) + nf + snr;
      return Nh(`Para ${what}: ancho de banda ${txt}, figura de ruido ${nf} dB y SNR mínima de ${mn(snr)} dB. ¿Sensibilidad en dBm?`, s, 'dBm', `−174 + 10·log(${bw}) + ${nf} + (${mn(snr)}) = ${fmt(s, 1)} dBm.`, 0.8, 'Suelo de ruido (−174 + 10·log(BW) + NF) más la SNR mínima, con su signo.');
    }, 'rf_sens');

    Gen.add('rf_margin', () => {
      const pt = pick([10, 14, 17, 20]), g = pick([2, 3, 5]), lc = pick([1, 2, 3]), f = pick([868, 433.92]), d = pick([1, 2, 5, 10, 15]), s = pick([-110, -115, -120, -125, -130]);
      const L = Math.round(20 * L10(d) + 20 * L10(f) + 32.44);
      const m = pt + 2 * g - lc - L - s;
      return Nh(`Emisor de ${pt} dBm, dos antenas de ${g} dBi, ${lc} dB de cables en total, ${L} dB de pérdidas de camino y sensibilidad de ${mn(s)} dBm. ¿Margen del enlace en dB?`, m, 'dB', `Pr = ${pt} + ${g} + ${g} − ${lc} − ${L} = ${pt + 2 * g - lc - L} dBm. Margen = Pr − sensibilidad = ${m} dB.`, 0.6, 'Calcula primero lo que llega (Pr) y réstale la sensibilidad, con su signo.');
    }, 'rf_budget');

    Gen.add('rf_lcf', () => {
      const L = pick([0.1, 0.22, 0.47, 1, 4.7, 10, 100, 220]), Cp = pick([10, 22, 47, 100, 220, 470]);
      const f = 1 / (2 * Math.PI * Math.sqrt(L * 1e-6 * Cp * 1e-12)) / 1e6;
      return Nh(`L = ${fmt(L)} µH y C = ${Cp} pF. ¿Frecuencia de resonancia en MHz?`, f, 'MHz', `f₀ = 1 / (2π·√(${fmt(L)}·10⁻⁶ × ${Cp}·10⁻¹²)) = ${fmt(f, 3)} MHz. Atajo: 159 / √(L·C) con µH y pF.`, Math.max(0.002, f * 0.03), 'Atajo: f₀ (MHz) ≈ 159 / √(L en µH × C en pF).');
    }, 'rf_resonance');

    Gen.add('rf_xl', () => {
      const [L, lt] = pick([[10, '10 nH'], [22, '22 nH'], [100, '100 nH'], [1000, '1 µH']]), [f, ft] = pick([[100, '100 MHz'], [433.92, '433,92 MHz'], [868, '868 MHz'], [2440, '2,44 GHz']]);
      const x = 2 * Math.PI * f * 1e6 * L * 1e-9;
      return Nh(`¿Reactancia de una inductancia de ${lt} a ${ft}? (en Ω)`, x, 'Ω', `XL = 2π · ${fmt(f)}·10⁶ · ${L}·10⁻⁹ ≈ ${fmt(x, 1)} Ω.`, Math.max(0.5, x * 0.03), 'XL = 2π·f·L con f en Hz y L en henrios: cuidado con los prefijos n y M.');
    }, 'rf_reactance');

    Gen.add('rf_qbw', () => {
      const [f0, ft] = pick([[1e6, '1 MHz'], [455e3, '455 kHz'], [10.7e6, '10,7 MHz'], [7e6, '7 MHz'], [600e3, '600 kHz']]), q = pick([10, 20, 50, 100, 200]);
      const bw = f0 / q / 1000;
      return Nh(`Un circuito resuena a ${ft} con Q = ${q}. ¿Ancho de banda a −3 dB en kHz?`, bw, 'kHz', `BW = f₀ / Q = ${fmt(bw, 2)} kHz.`, Math.max(0.05, bw * 0.02), 'BW = f₀ / Q. Pasa f₀ a kHz antes de dividir.');
    }, 'rf_q');

    Gen.add('rf_harm', () => {
      const f = pick([27.12, 144, 433.92, 868, 2440]), n = pick([2, 3, 5]);
      const r = x => fmt(x, 2) + ' MHz';
      return MC(`Un emisor de ${fmt(f)} MHz sin filtrar. ¿Dónde cae su armónico número ${n}?`, r(n * f), [r(f / n), r(f + n), r((n + 1) * f), r(n * f / 2)], `Armónico n = n × f = ${n} × ${fmt(f)} = ${r(n * f)}.`, { h: 'Los armónicos son múltiplos enteros de la fundamental.' });
    }, 'rf_harmonics');

    Gen.add('rf_ppmGen', () => {
      const [f, ft] = pick([[433.92, '433,92 MHz'], [868, '868 MHz'], [915, '915 MHz'], [2440, '2,44 GHz'], [137.1, '137,1 MHz']]), ppm = pick([0.5, 2.5, 10, 20, 30, 50]);
      const k = f * ppm / 1000;
      return Nh(`Un oscilador de ±${fmt(ppm)} ppm a ${ft}. ¿Error máximo en kHz?`, k, 'kHz', `${fmt(f)}·10⁶ × ${fmt(ppm)}·10⁻⁶ = ${fmt(k * 1000, 0)} Hz = ${fmt(k, 2)} kHz.`, Math.max(0.01, k * 0.02), 'Multiplica la frecuencia en Hz por los ppm y divide entre un millón.');
    }, 'rf_ppm');

    Gen.add('rf_pllGen', () => {
      const fr = pick([10, 25, 26, 32]), fo = pick([433.92, 868, 869.525, 915, 2440]), N0 = fo / fr;
      return Nh(`Un PLL con referencia de ${fr} MHz debe dar ${fmt(fo)} MHz. ¿Qué divisor N necesita?`, N0, '', `N = fsal / fref = ${fmt(fo)} / ${fr} = ${fmt(N0, 4)}. Un PLL fraccionario admite N no entero.`, 0.005, 'fsal = N · fref: despeja N.');
    }, 'rf_osc');

    Gen.add('rf_lo', () => {
      if (Math.random() < 0.5) {
        const f = pick([88.5, 91.2, 95, 98.4, 101.7, 104.2]), up = pick([true, false]);
        const r = x => fmt(x, 1) + ' MHz', lo = up ? f + 10.7 : f - 10.7;
        return MC(`Receptor de FM con FI de 10,7 MHz y oscilador local por ${up ? 'encima' : 'debajo'} de la emisora. Sintonizas ${fmt(f)} MHz. ¿Dónde va el oscilador?`, r(lo), [r(up ? f - 10.7 : f + 10.7), r(f + 21.4), r(10.7), r(f)], `${up ? 'OL = RF + FI' : 'OL = RF − FI'} = ${r(lo)}.`, { h: '|OL − RF| tiene que dar la FI: mira si el oscilador va por encima o por debajo.' });
      }
      const f = pick([594, 774, 999, 1107, 1260]), lo = f + 455;
      return MC(`Receptor de onda media con FI de 455 kHz y oscilador local por encima. Sintonizas ${f} kHz. ¿Dónde va el oscilador?`, lo + ' kHz', [(f - 455) + ' kHz', (f + 910) + ' kHz', '455 kHz', f + ' kHz'], `OL = RF + FI = ${f} + 455 = ${lo} kHz.`, { h: 'Con el oscilador por encima, OL = RF + FI.' });
    }, 'rf_mixer');

    Gen.add('rf_image', () => {
      if (Math.random() < 0.5) {
        const f = pick([88.5, 91.2, 96.3, 101.7, 104.2]), fi = 10.7;
        const r = x => fmt(x, 1) + ' MHz';
        return MC(`Receptor de FM con FI = 10,7 MHz y oscilador local por encima. Sintonizas ${fmt(f)} MHz. ¿Frecuencia imagen?`, r(f + 2 * fi), [r(f + fi), r(f - 2 * fi), r(f - fi), r(2 * f)], `OL = ${fmt(f)} + 10,7 = ${fmt(f + fi, 1)} MHz. La imagen está otra FI más arriba: ${r(f + 2 * fi)}.`, { h: 'La imagen está al otro lado del oscilador, a la misma distancia: RF + 2·FI.' });
      }
      const f = pick([585, 657, 774, 855, 1035, 1215]), fi = 455;
      const r = x => fmt(x) + ' kHz';
      return MC(`Receptor de onda media con FI = 455 kHz y oscilador local por encima. Sintonizas ${f} kHz. ¿Frecuencia imagen?`, r(f + 2 * fi), [r(f + fi), r(Math.abs(f - 2 * fi)), r(f - fi > 0 ? f - fi : f + 3 * fi), r(2 * f)], `OL = ${f} + 455 = ${f + fi} kHz; imagen = RF + 2·FI = ${r(f + 2 * fi)}.`, { h: 'Primero sitúa el oscilador (RF + FI); la imagen está otra FI más allá.' });
    }, 'rf_image');

    Gen.add('rf_im3', () => {
      const f1 = pick([100, 144.5, 433, 868.1]), dlt = pick([0.2, 0.5, 1, 2]), f2 = +(f1 + dlt).toFixed(2);
      const r = x => fmt(x, 2) + ' MHz';
      return MC(`Dos señales fuertes en ${fmt(f1)} y ${fmt(f2)} MHz saturan un amplificador. ¿Dónde caen los productos de tercer orden?`, r(2 * f1 - f2) + ' y ' + r(2 * f2 - f1), [r(f2 - f1) + ' y ' + r(f1 + f2), r(2 * f1) + ' y ' + r(2 * f2), r(3 * f1) + ' y ' + r(3 * f2)], `2·${fmt(f1)} − ${fmt(f2)} = ${r(2 * f1 - f2)} y 2·${fmt(f2)} − ${fmt(f1)} = ${r(2 * f2 - f1)}: justo al lado de las señales.`, { h: 'Tercer orden: 2f₁ − f₂ y 2f₂ − f₁.' });
    }, 'rf_overload');

    Gen.add('rf_swr', () => {
      const c = ri(0, 2), h = 'Calcula |Γ| = |ZL − 50| / (ZL + 50) y luego ROE = (1 + |Γ|) / (1 − |Γ|).';
      if (c === 0) {
        const R = pick([12.5, 25, 35, 75, 100, 150, 200]);
        const g = Math.abs(R - 50) / (R + 50), s = (1 + g) / (1 - g);
        return Nh(`Una línea de 50 Ω termina en una carga resistiva de ${fmt(R)} Ω. ¿ROE?`, s, ':1', `|Γ| = |${fmt(R)} − 50| / (${fmt(R)} + 50) = ${fmt(g, 3)}; ROE = (1 + |Γ|) / (1 − |Γ|) = ${fmt(s, 2)}. Con cargas resistivas, ROE = mayor / menor.`, 0.05, 'Con cargas resistivas puras, ROE = la mayor de las dos impedancias entre la menor.');
      }
      if (c === 1) {
        const g = pick([0.05, 0.1, 0.2, 0.25, 0.33, 0.5]), s = (1 + g) / (1 - g);
        return Nh(`El coeficiente de reflexión vale |Γ| = ${fmt(g)}. ¿ROE?`, s, ':1', `ROE = (1 + ${fmt(g)}) / (1 − ${fmt(g)}) = ${fmt(s, 2)}.`, 0.03, h);
      }
      const g = pick([0.1, 0.2, 0.316, 0.5]), rl = -20 * L10(g);
      return Nh(`|Γ| = ${fmt(g)}. ¿Pérdidas de retorno en dB?`, rl, 'dB', `RL = −20·log(${fmt(g)}) = ${fmt(rl, 1)} dB. Cuantos más dB, mejor adaptada.`, 0.3, 'RL = −20·log|Γ|: aquí es 20 porque Γ es una relación de tensiones.');
    }, 'rf_line');

    Gen.add('rf_qwt', () => {
      const [z1, z2] = pick([[50, 200], [50, 100], [12.5, 50], [50, 75], [25, 50], [50, 300]]);
      const z0 = Math.sqrt(z1 * z2);
      return Nh(`¿Qué impedancia debe tener un tramo de λ/4 para adaptar ${fmt(z2)} Ω a ${fmt(z1)} Ω?`, z0, 'Ω', `Z0 = √(${fmt(z1)} × ${fmt(z2)}) = ${fmt(z0, 1)} Ω.`, 0.5, 'El transformador de λ/4 usa la media geométrica: √(Z₁·Z₂).');
    }, 'rf_match');

    Gen.add('rf_vf', () => {
      const [f, ft] = pick([[145, '145 MHz'], [433.92, '433,92 MHz'], [868, '868 MHz'], [1090, '1090 MHz']]), vf = pick([0.66, 0.8, 0.85]);
      const q = C / f / 4 * 100, phys = q * vf;
      return Nh(`Necesitas un tramo de coaxial de λ/4 eléctrico a ${ft} con un cable de VF = ${fmt(vf)}. ¿Longitud física en cm?`, phys, 'cm', `λ/4 en el aire = ${fmt(q, 1)} cm; × ${fmt(vf)} = ${fmt(phys, 1)} cm.`, Math.max(0.3, phys * 0.02), 'Calcula λ/4 en el aire y multiplica por el factor de velocidad: dentro del cable la onda va más lenta.');
    }, 'rf_tline');

    Gen.add('rf_carson', () => {
      const [df, fm, what] = pick([[75, 15, 'una emisora de FM comercial (audio mono)'], [5, 3, 'un walkie de FM de banda estrecha'], [2.5, 3, 'un equipo con canales de 12,5 kHz'], [50, 10, 'un enlace de audio de prueba'], [25, 5, 'un transmisor de telemetría FM']]);
      return Nh(`¿Ancho de banda, según Carson, de ${what}: desviación ${fmt(df)} kHz y audio de hasta ${fmt(fm)} kHz? (en kHz)`, 2 * (df + fm), 'kHz', `BW ≈ 2 × (Δf + fm) = 2 × (${fmt(df)} + ${fmt(fm)}) = ${fmt(2 * (df + fm))} kHz.`, 0.5, 'Carson: suma desviación y audio, y multiplica por 2.');
    }, 'rf_fm');

    Gen.add('rf_amBw', () => {
      const fc = pick([531, 594, 702, 1008, 1179, 1494]), fm = pick([3, 4.5, 5]);
      const r = (a, b) => `De ${fmt(a, 1)} a ${fmt(b, 1)} kHz`;
      return MC(`Una emisora de AM en ${fc} kHz transmite audio de hasta ${fmt(fm)} kHz. ¿Qué tramo ocupa?`, r(fc - fm, fc + fm), [r(fc, fc + fm), r(fc - 2 * fm, fc + 2 * fm), r(fc - fm / 2, fc + fm / 2)], `Bandas laterales en fc ± fm: ${r(fc - fm, fc + fm)} (ancho ${fmt(2 * fm)} kHz).`, { h: 'Una banda lateral a cada lado de la portadora, separadas fm.' });
    }, 'rf_am');

    Gen.add('rf_bits', () => {
      const [m, name] = pick([[2, 'BPSK'], [4, 'QPSK'], [8, '8-PSK'], [16, '16-QAM'], [64, '64-QAM'], [256, '256-QAM'], [1024, '1024-QAM']]), b = Math.round(Math.log2(m));
      return MC(`¿Cuántos bits lleva cada símbolo en ${name} (${m} estados)?`, String(b), [String(m), String(m / 2), String(b * 2)], `log₂(${m}) = ${b}: 2^${b} = ${m}.`, { h: '¿A qué potencia hay que elevar 2 para obtener el número de estados?' });
    }, 'rf_symbols');

    Gen.add('rf_tsym', () => {
      const sf = ri(7, 12), bw = pick([125, 250, 500]);
      const t = Math.pow(2, sf) / bw;
      return Nh(`LoRa SF${sf} con ${bw} kHz. ¿Duración de un símbolo en ms?`, t, 'ms', `Tsímbolo = 2^${sf} / ${bw} kHz = ${Math.pow(2, sf)} / ${bw} = ${fmt(t, 3)} ms.`, Math.max(0.01, t * 0.02), '2^SF entre el ancho de banda en kHz da milisegundos.');
    }, 'rf_lora');

    Gen.add('rf_toaRatio', () => {
      const sf = ri(7, 10), up = pick([1, 2]);
      const a = loraToa(sf, 125, 20, 1).ms, b = loraToa(sf + up, 125, 20, 1).ms, k = b / a;
      const s = x => '×' + fmt(x, 1);
      return MC(`Un paquete de 20 bytes con SF${sf} y 125 kHz tarda ${fmt(a, 1)} ms. ¿Aproximadamente cuánto más tarda con SF${sf + up}?`, s(k), [s(k * 2), s(k / 2), s(1 + up * 0.1), s(k * 4)], `Con SF${sf + up} tarda ${fmt(b, 1)} ms: ${s(k)}. Cada paso de SF casi duplica el tiempo en aire.`, { h: 'Cada paso de SF duplica la duración del símbolo; el paquete crece algo menos que el doble.' });
    }, 'rf_lora');

    Gen.add('rf_lorasens', () => {
      const sf = ri(7, 12), bw = pick([125, 250]), nf = 6;
      const s = -174 + 10 * L10(bw * 1000) + nf + LORA_SNR[sf];
      return Nh(`LoRa SF${sf}, ${bw} kHz, figura de ruido 6 dB. El demodulador necesita una SNR de ${mn(fmt(LORA_SNR[sf], 1))} dB. ¿Sensibilidad en dBm?`, s, 'dBm', `−174 + 10·log(${bw * 1000}) + 6 + (${mn(fmt(LORA_SNR[sf], 1))}) = ${fmt(s, 1)} dBm. La SNR negativa es la ventaja del ensanchado.`, 0.8, 'La misma cuenta de siempre; aquí la SNR mínima es negativa: súmala con su signo.');
    }, 'rf_lorasnr');

    Gen.add('rf_duty', () => {
      const ms = pick([56, 103, 185, 371, 741, 1319]), [dc, txt] = pick([[0.01, '1 %'], [0.001, '0,1 %'], [0.1, '10 %']]);
      const n = Math.floor(3600000 * dc / ms);
      return Nh(`Cada paquete pasa ${ms} ms en el aire y la sub-banda limita el ciclo de trabajo al ${txt}. ¿Cuántos paquetes, como máximo, por hora?`, n, '', `${txt} de 3600 s = ${fmt(3600 * dc)} s = ${fmt(3600000 * dc)} ms; ${fmt(3600000 * dc)} / ${ms} ≈ ${n} paquetes.`, 1, 'Calcula los segundos permitidos por hora, pásalos a ms y divide entre lo que dura un paquete.');
    }, 'rf_duty');

    Gen.add('rf_nrf', () => {
      const ch = pick([2, 10, 26, 40, 76, 80, 90, 108, 125]);
      const r = x => x + ' MHz';
      const legal = 2400 + ch <= 2482;
      return MC(`Configuras un nRF24L01+ en el canal ${ch}. ¿En qué frecuencia transmite?`, r(2400 + ch), [r(2400 + 2 * ch), r(2402 + 2 * ch), r(2412 + 5 * ch), r(2400 + ch * 10)], `f = 2400 + canal MHz = ${2400 + ch} MHz. ${legal ? 'Dentro de la banda ISM europea (2400–2483,5 MHz).' : '¡Fuera de la banda ISM europea! Solo puedes escuchar ahí, nunca transmitir.'}`, { h: 'Cada canal del nRF24 es 1 MHz: súmalo a 2400.' });
    }, 'rf_24ghz');

    Gen.add('rf_retry', () => {
      const d = ri(0, 15), n = ri(2, 15), us = (d + 1) * 250, f = x => x >= 1000 ? fmt(x / 1000, 2) + ' ms' : x + ' µs';
      return MC(`radio.setRetries(${d}, ${n}): ¿cuánto espera el emisor entre reintentos?`, f(us), [f(d ? d * 250 : 500), f(us * n), f((n + 1) * 250), f(d * 1000 + 1000)], `(${d} + 1) × 250 µs = ${us} µs. El segundo número (${n}) es cuántos reintentos hace como máximo.`, { h: 'El primer parámetro cuenta pasos de 250 µs, empezando en 1, no en 0.' });
    }, 'rf_nrf');

    Gen.add('rf_dopplerGen', () => {
      const [f, ft] = pick([[137.1, '137,1 MHz'], [145.8, '145,8 MHz'], [435, '435 MHz'], [1575.42, '1575,42 MHz']]), v = pick([3, 5, 6.5, 7]);
      const k = f * v / 299.792458;
      return Nh(`Un satélite se acerca a ${fmt(v)} km/s en tu línea de visión y emite en ${ft}. ¿Desplazamiento Doppler en kHz?`, k, 'kHz', `Δf = f·v/c = ${fmt(f)}·10⁶ × ${fmt(v * 1000)} / 3·10⁸ ≈ ${fmt(k, 2)} kHz (hacia arriba, porque se acerca).`, Math.max(0.05, k * 0.03), 'Δf = f · v / c, con v y c en las mismas unidades (km/s).');
    }, 'rf_doppler');

    Gen.add('rf_rssiD', () => {
      const A = pick([-55, -59, -62]), n = pick([2, 2.5, 3]), dd = pick([10, 15, 20, 25, 30]), rssi = A - dd;
      const d = Math.pow(10, dd / (10 * n));
      return Nh(`RSSI a 1 m: ${mn(A)} dBm. Exponente n = ${fmt(n)}. Mides ${mn(rssi)} dBm. ¿Distancia estimada en m?`, d, 'm', `d = 10^((${mn(A)} − (${mn(rssi)})) / (10 × ${fmt(n)})) = 10^(${dd} / ${fmt(10 * n)}) ≈ ${fmt(d, 2)} m.`, Math.max(0.1, d * 0.03), 'Resta primero: cuántos dB has perdido respecto a 1 m. Luego d = 10^(dB / (10·n)).');
    }, 'rf_pathlaw');

    Gen.add('rf_fresnel', () => {
      const d = pick([0.5, 1, 2, 5, 10, 20]), [f, ft] = pick([[0.43392, '433,92 MHz'], [0.868, '868 MHz'], [2.44, '2,44 GHz']]);
      const r = 8.66 * Math.sqrt(d / f);
      return Nh(`Enlace de ${fmt(d)} km a ${ft}. ¿Radio de la primera zona de Fresnel en el punto medio (en metros)?`, r, 'm', `r ≈ 8,66 · √(d km / f GHz) = 8,66 · √(${fmt(d)} / ${fmt(f, 3)}) = ${fmt(r, 1)} m. Despeja al menos el 60 %: ${fmt(r * 0.6, 1)} m.`, Math.max(0.1, r * 0.03), 'Distancia en km y frecuencia en GHz dentro de la raíz; luego × 8,66.');
    }, 'rf_fresnel');
  }

  /* ===================== VISUALIZACIONES ===================== */
  const pts = a => a.map((p, i) => (i ? 'L' : 'M') + p[0].toFixed(1) + ' ' + p[1].toFixed(1)).join('');
