          <rect x="${X(Math.max(0.7, x1)).toFixed(1)}" y="40" width="${Math.max(1, X(Math.min(1.3, x2)) - X(Math.max(0.7, x1))).toFixed(1)}" height="110" fill="var(--led)" opacity=".15"/>
